/* ============================================================
   Ad Fontes Project — Catecismos reformados
   Preguntas y respuestas. Textos de dominio público, en español.
   Las referencias entre corchetes se convierten en enlaces a la Biblia.
   ============================================================ */

const CATECISMOS = {

  baptista1693: {
    titulo: 'Catecismo Bautista (1693)',
    sub: 'Bautista · 1693',
    nota: 'También llamado Catecismo de Keach. Compuesto por los bautistas particulares (Benjamin Keach y William Collins) siguiendo de cerca el Catecismo Menor de Westminster, con los distintivos bautistas sobre el bautismo de creyentes y la Cena del Señor. Sigue a la Confesión de 1689.',
    fuente: 'Catecismo Bautista de 1693 · texto de dominio público. Toca una referencia para leerla en la Biblia.',
    preguntas: [
      { p: '¿Quién es el primer y principal Ser?', r: 'Dios es el primer y principal Ser.', refs: ['Is 44:6','Sal 97:9'] },
      { p: '¿Debe todo hombre creer que hay Dios?', r: 'Todo hombre debe creer que hay Dios, y es su gran pecado y locura no creerlo.', refs: ['He 11:6','Sal 14:1'] },
      { p: '¿Cómo podemos saber que hay Dios?', r: 'La luz de la naturaleza en el hombre y las obras de Dios declaran claramente que hay Dios; pero solo su Palabra y su Espíritu lo revelan de manera plena y eficaz para la salvación de los pecadores.', refs: ['Sal 19:1-3','Ro 1:19-20','2 Ti 3:15','1 Co 2:10'] },
      { p: '¿Qué es la Palabra de Dios?', r: 'Las Santas Escrituras del Antiguo y Nuevo Testamento son la Palabra de Dios, y la única regla segura de fe y obediencia.', refs: ['2 Ti 3:16','Ef 2:20'] },
      { p: '¿Pueden todos los hombres usar las Santas Escrituras?', r: 'Todos los hombres no solo tienen permiso, sino mandato y exhortación de leer, oír y entender las Santas Escrituras.', refs: ['Jn 5:39','Lc 16:29','Hch 17:11'] },
      { p: '¿Qué enseñan principalmente las Escrituras?', r: 'Las Escrituras enseñan principalmente lo que el hombre ha de creer acerca de Dios, y qué deber Dios requiere del hombre.', refs: ['2 Ti 1:13','2 Ti 3:16'] },
      { p: '¿Qué es Dios?', r: 'Dios es Espíritu, infinito, eterno e inmutable en su ser, sabiduría, poder, santidad, justicia, bondad y verdad.', refs: ['Jn 4:24','Job 11:7-9','Sal 90:2','Stg 1:17','Éx 34:6-7'] },
      { p: '¿Hay más de un Dios?', r: 'Hay un solo Dios, el vivo y verdadero.', refs: ['Dt 6:4','Jer 10:10'] },
      { p: '¿Cuántas personas hay en la Deidad?', r: 'Hay tres personas en la Deidad: el Padre, el Hijo y el Espíritu Santo; y estas tres son un solo Dios, de una misma sustancia, iguales en poder y gloria.', refs: ['1 Jn 5:7','Mt 28:19'] },
      { p: '¿Cuáles son los decretos de Dios?', r: 'Los decretos de Dios son su propósito eterno, según el consejo de su voluntad, por el cual, para su propia gloria, ha preordenado todo cuanto sucede.', refs: ['Ef 1:11','Ro 11:36','Dn 4:35'] },
      { p: '¿Cómo ejecuta Dios sus decretos?', r: 'Dios ejecuta sus decretos en las obras de la creación y de la providencia.', refs: ['Ap 4:11','Dn 4:35'] },
      { p: '¿Qué es la obra de la creación?', r: 'La obra de la creación es aquella por la cual Dios hizo todas las cosas de la nada, por la palabra de su poder, en el espacio de seis días, y todo muy bueno.', refs: ['Gn 1:1','He 11:3','Éx 20:11','Gn 1:31'] },
      { p: '¿Cómo creó Dios al hombre?', r: 'Dios creó al hombre, varón y mujer, a su propia imagen, en conocimiento, justicia y santidad, con dominio sobre las criaturas.', refs: ['Gn 1:26-28','Col 3:10','Ef 4:24'] },
      { p: '¿Cuáles son las obras de la providencia de Dios?', r: 'Las obras de la providencia de Dios son su santísima, sapientísima y poderosísima preservación y gobierno de todas sus criaturas y de todas sus acciones.', refs: ['Sal 145:17','Sal 103:19','Mt 10:29-31','He 1:3'] },
      { p: '¿Qué acto especial de providencia ejerció Dios hacia el hombre en el estado en que fue creado?', r: 'Cuando Dios creó al hombre, hizo con él un pacto de vida bajo la condición de una obediencia perfecta, prohibiéndole comer del árbol del conocimiento del bien y del mal, bajo pena de muerte.', refs: ['Gá 3:12','Gn 2:17'] },
      { p: '¿Permanecieron nuestros primeros padres en el estado en que fueron creados?', r: 'Nuestros primeros padres, dejados a la libertad de su propia voluntad, cayeron del estado en que fueron creados, pecando contra Dios al comer del fruto prohibido.', refs: ['Ec 7:29','Gn 3:6-8'] },
      { p: '¿Cayó toda la humanidad en la primera transgresión de Adán?', r: 'Habiéndose hecho el pacto con Adán no solo para él, sino también para su posteridad, toda la humanidad que desciende de él por generación ordinaria pecó en él y cayó con él en su primera transgresión.', refs: ['1 Co 15:21-22','Ro 5:12,18-19'] },
      { p: '¿Qué es el pecado?', r: 'El pecado es toda falta de conformidad con la ley de Dios, o toda transgresión de ella.', refs: ['1 Jn 3:4'] },
      { p: '¿A qué estado llevó la caída a la humanidad?', r: 'La caída llevó a la humanidad a un estado de pecado y de miseria.', refs: ['Ro 5:12'] },
      { p: '¿En qué consiste la pecaminosidad de aquel estado en que cayó el hombre?', r: 'La pecaminosidad de aquel estado consiste en la culpa del primer pecado de Adán, la falta de justicia original y la corrupción de toda su naturaleza, que comúnmente se llama pecado original, junto con todas las transgresiones que de él proceden.', refs: ['Ro 5:12','Ro 5:19','Ef 2:1-3','Stg 1:14-15','Mt 15:19'] },
      { p: '¿Cuál es la miseria de aquel estado en que cayó el hombre?', r: 'Toda la humanidad, por su caída, perdió la comunión con Dios, quedó bajo su ira y maldición, y así hecha sujeta a todas las miserias de esta vida, a la muerte misma, y a las penas del infierno para siempre.', refs: ['Gn 3:8,24','Ef 2:3','Gá 3:10','Lm 3:39','Ro 6:23','Mt 25:41'] },
      { p: '¿Dejó Dios que toda la humanidad pereciera en el estado de pecado y miseria?', r: 'Dios, por su mero beneplácito, desde toda la eternidad, habiendo escogido a algunos para vida eterna, entró en un pacto de gracia para librarlos del estado de pecado y miseria, y traerlos a un estado de salvación por un Redentor.', refs: ['Ef 1:3-4','2 Ts 2:13-14','Ro 5:21'] },
      { p: '¿Quién es el Redentor de los elegidos de Dios?', r: 'El único Redentor de los elegidos de Dios es el Señor Jesucristo, quien, siendo el eterno Hijo de Dios, se hizo hombre, y así fue y sigue siendo Dios y hombre, en dos naturalezas distintas y una sola persona, para siempre.', refs: ['1 Ti 2:5-6','Jn 1:14','Gá 4:4','Lc 1:35','Col 2:9','He 7:24-25'] },
      { p: '¿Cómo llegó Cristo, siendo el Hijo de Dios, a ser hombre?', r: 'Cristo, el Hijo de Dios, se hizo hombre tomando para sí un cuerpo verdadero y un alma racional, siendo concebido por el poder del Espíritu Santo en el vientre de la virgen María, y nacido de ella, mas sin pecado.', refs: ['Jn 1:14','He 2:14,16-17','Lc 1:27,31,35','He 4:15'] },
      { p: '¿Qué oficios cumple Cristo como nuestro Redentor?', r: 'Cristo, como nuestro Redentor, cumple los oficios de profeta, de sacerdote y de rey, tanto en su estado de humillación como en el de exaltación.', refs: ['Hch 3:22','He 5:5-6','Sal 2:6'] },
      { p: '¿Cómo cumple Cristo el oficio de profeta?', r: 'Cristo cumple el oficio de profeta al revelarnos, por su Palabra y su Espíritu, la voluntad de Dios para nuestra salvación.', refs: ['Jn 1:18','1 P 1:10-12','Jn 15:15','Jn 20:31'] },
      { p: '¿Cómo cumple Cristo el oficio de sacerdote?', r: 'Cristo cumple el oficio de sacerdote al ofrecerse a sí mismo una sola vez en sacrificio para satisfacer la justicia divina y reconciliarnos con Dios, y al interceder continuamente por nosotros.', refs: ['He 9:14,28','He 2:17','He 7:24-25'] },
      { p: '¿Cómo cumple Cristo el oficio de rey?', r: 'Cristo cumple el oficio de rey al sujetarnos a sí mismo, gobernarnos y defendernos, y refrenar y vencer a todos sus enemigos y los nuestros.', refs: ['Sal 110:3','1 Co 15:25','Col 1:13'] },
      { p: '¿En qué consistió la humillación de Cristo?', r: 'La humillación de Cristo consistió en haber nacido, y eso en baja condición; en ser hecho bajo la ley; en padecer las miserias de esta vida, la ira de Dios y la muerte maldita de la cruz; en ser sepultado y permanecer bajo el poder de la muerte por un tiempo.', refs: ['Lc 2:7','Gá 4:4','Is 53:2-3','Lc 22:44','Fil 2:8','1 Co 15:3-4'] },
      { p: '¿En qué consiste la exaltación de Cristo?', r: 'La exaltación de Cristo consiste en su resurrección de entre los muertos al tercer día, su ascensión al cielo, su sesión a la diestra de Dios Padre, y su venida para juzgar al mundo en el día postrero.', refs: ['1 Co 15:4','Mr 16:19','Ef 1:20','Hch 1:11','Hch 17:31'] },
      { p: '¿Cómo somos hechos partícipes de la redención comprada por Cristo?', r: 'Somos hechos partícipes de la redención comprada por Cristo por la aplicación eficaz de ella a nosotros, por su Santo Espíritu.', refs: ['Jn 1:12','Tit 3:5-6','Jn 3:5-6'] },
      { p: '¿Cómo aplica el Espíritu la redención comprada por Cristo?', r: 'El Espíritu aplica la redención comprada por Cristo obrando en nosotros la fe, y uniéndonos así a Cristo en nuestro llamamiento eficaz.', refs: ['Ef 2:8','Ef 3:17','1 Co 1:9'] },
      { p: '¿Qué es el llamamiento eficaz?', r: 'El llamamiento eficaz es la obra del Espíritu de Dios, por la cual, convenciéndonos de nuestro pecado y miseria, iluminando nuestras mentes en el conocimiento de Cristo, y renovando nuestra voluntad, nos persuade y capacita para abrazar a Jesucristo, ofrecido gratuitamente a nosotros en el evangelio.', refs: ['2 Ti 1:9','2 Ts 2:13-14','Hch 26:18','Ez 36:26-27','Jn 6:44-45','Fil 2:13'] },
      { p: '¿De qué beneficios participan en esta vida los que son llamados eficazmente?', r: 'Los que son llamados eficazmente participan en esta vida de la justificación, la adopción, la santificación, y los diversos beneficios que en esta vida las acompañan o de ellas proceden.', refs: ['Ro 8:30','Ef 1:5','1 Co 6:11','Ro 5:1-2,5'] },
      { p: '¿Qué es la justificación?', r: 'La justificación es un acto de la gracia gratuita de Dios, por el cual perdona todos nuestros pecados y nos acepta como justos ante sus ojos, solo por causa de la justicia de Cristo imputada a nosotros, y recibida solo por la fe.', refs: ['Ro 3:24','Ef 1:7','2 Co 5:19,21','Ro 5:19','Gá 2:16','Fil 3:9'] },
      { p: '¿Qué es la adopción?', r: 'La adopción es un acto de la gracia gratuita de Dios, por el cual somos recibidos en el número de los hijos de Dios y tenemos derecho a todos sus privilegios.', refs: ['1 Jn 3:1','Jn 1:12','Ro 8:17'] },
      { p: '¿Qué es la santificación?', r: 'La santificación es la obra de la gracia gratuita de Dios, por la cual somos renovados en todo nuestro ser a imagen de Dios, y capacitados cada vez más para morir al pecado y vivir para la justicia.', refs: ['2 Ts 2:13','Ef 4:23-24','Ro 6:4,6','Ro 8:1'] },
      { p: '¿Qué beneficios acompañan o proceden en esta vida de la justificación, la adopción y la santificación?', r: 'Los beneficios que en esta vida acompañan o proceden de la justificación, la adopción y la santificación son: la seguridad del amor de Dios, la paz de conciencia, el gozo en el Espíritu Santo, el crecimiento en gracia, y la perseverancia en ella hasta el fin.', refs: ['Ro 5:1-2,5','Ro 14:17','Pr 4:18','1 Jn 5:13','1 P 1:5'] },
      { p: '¿Qué beneficios reciben los creyentes de Cristo en la muerte?', r: 'Las almas de los creyentes son, en su muerte, hechas perfectas en santidad, y pasan inmediatamente a la gloria; y sus cuerpos, unidos todavía a Cristo, descansan en sus sepulcros hasta la resurrección.', refs: ['He 12:23','Fil 1:23','2 Co 5:8','1 Ts 4:14','Is 57:2','Job 19:26'] },
      { p: '¿Qué beneficios reciben los creyentes de Cristo en la resurrección?', r: 'En la resurrección, los creyentes, siendo resucitados en gloria, serán reconocidos y absueltos abiertamente en el día del juicio, y hechos perfectamente bienaventurados, en el pleno gozo de Dios, por toda la eternidad.', refs: ['1 Co 15:43','Mt 25:23','1 Jn 3:2','1 Ts 4:17'] },
      { p: '¿Qué será de los malvados en su muerte?', r: 'Las almas de los malvados serán, en su muerte, arrojadas a los tormentos del infierno, y sus cuerpos yacerán en sus sepulcros hasta la resurrección y el juicio del gran día.', refs: ['Lc 16:22-24','Sal 49:14','Jn 5:28-29'] },
      { p: '¿Cuál es el deber que Dios requiere del hombre?', r: 'El deber que Dios requiere del hombre es la obediencia a su voluntad revelada.', refs: ['Miq 6:8','1 S 15:22'] },
      { p: '¿Qué reveló Dios primeramente al hombre como regla de su obediencia?', r: 'La regla que Dios reveló primeramente al hombre para su obediencia fue la ley moral.', refs: ['Ro 2:14-15','Dt 10:4'] },
      { p: '¿Dónde está resumida la ley moral?', r: 'La ley moral está resumida en los Diez Mandamientos.', refs: ['Dt 10:4','Mt 19:17'] },
      { p: '¿Cuál es el resumen de los Diez Mandamientos?', r: 'El resumen de los Diez Mandamientos es amar al Señor nuestro Dios con todo nuestro corazón, con toda nuestra alma, con todas nuestras fuerzas y con toda nuestra mente; y a nuestro prójimo como a nosotros mismos.', refs: ['Mt 22:37-40'] },
      { p: '¿Cuál es el prefacio a los Diez Mandamientos?', r: 'El prefacio a los Diez Mandamientos es: «Yo soy Jehová tu Dios, que te saqué de la tierra de Egipto, de casa de servidumbre».', refs: ['Éx 20:2'] },
      { p: '¿Qué nos enseña el prefacio a los Diez Mandamientos?', r: 'El prefacio nos enseña que, por cuanto Dios es el Señor, y nuestro Dios y Redentor, estamos obligados a guardar todos sus mandamientos.', refs: ['Lc 1:74-75','1 P 1:15-19'] },
      { p: '¿Cuál es el primer mandamiento?', r: 'El primer mandamiento es: «No tendrás dioses ajenos delante de mí».', refs: ['Éx 20:3'] },
      { p: '¿Qué se requiere en el primer mandamiento?', r: 'El primer mandamiento requiere que conozcamos y reconozcamos a Dios como el único Dios verdadero, y Dios nuestro, y que le adoremos y glorifiquemos en consecuencia.', refs: ['1 Cr 28:9','Dt 26:17','Mt 4:10'] },
      { p: '¿Qué se prohíbe en el primer mandamiento?', r: 'El primer mandamiento prohíbe negar o no adorar y glorificar al Dios verdadero como Dios nuestro, y dar aquella adoración y gloria a cualquier otro que solo a él pertenece.', refs: ['Sal 14:1','Ro 1:20-21,25'] },
      { p: '¿Cuál es el segundo mandamiento?', r: '«No te harás imagen, ni ninguna semejanza de lo que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra. No te inclinarás a ellas, ni las honrarás...».', refs: ['Éx 20:4-6'] },
      { p: '¿Qué se requiere en el segundo mandamiento?', r: 'El segundo mandamiento requiere que recibamos, observemos y guardemos puros y enteros todo el culto y las ordenanzas religiosas que Dios ha establecido en su Palabra.', refs: ['Dt 32:46','Mt 28:20','Dt 12:32'] },
      { p: '¿Qué se prohíbe en el segundo mandamiento?', r: 'El segundo mandamiento prohíbe adorar a Dios por medio de imágenes, o de cualquier otra manera no señalada en su Palabra.', refs: ['Dt 4:15-19','Éx 32:5,8','Col 2:18'] },
      { p: '¿Cuáles son las razones añadidas al segundo mandamiento?', r: 'Las razones añadidas al segundo mandamiento son: el señorío de Dios sobre nosotros, su propiedad sobre nosotros, y el celo que tiene por su propio culto.', refs: ['Sal 45:11','Éx 34:14','1 Co 10:22'] },
      { p: '¿Cuál es el tercer mandamiento?', r: '«No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano».', refs: ['Éx 20:7'] },
      { p: '¿Qué se requiere en el tercer mandamiento?', r: 'El tercer mandamiento requiere el uso santo y reverente de los nombres, títulos, atributos, ordenanzas, Palabra y obras de Dios.', refs: ['Sal 29:2','Ap 15:3-4','Ec 5:1'] },
      { p: '¿Qué se prohíbe en el tercer mandamiento?', r: 'El tercer mandamiento prohíbe todo abuso o profanación de aquello por lo cual Dios se da a conocer.', refs: ['Mal 1:6-7','Lv 19:12','Mt 5:33-37'] },
      { p: '¿Cuál es el cuarto mandamiento?', r: '«Acuérdate del día de reposo para santificarlo. Seis días trabajarás... mas el séptimo día es reposo para Jehová tu Dios...».', refs: ['Éx 20:8-11'] },
      { p: '¿Qué se requiere en el cuarto mandamiento?', r: 'El cuarto mandamiento requiere que se guarde santo para Dios el tiempo que él ha señalado en su Palabra, particularmente un día entero de cada siete, como día de reposo santo para él.', refs: ['Éx 20:8,10','Lv 19:30'] },
      { p: '¿Cuál es el día de reposo señalado para los cristianos?', r: 'Desde la resurrección de Cristo, el primer día de la semana, llamado el Día del Señor, es el día de reposo cristiano, que ha de continuar hasta el fin del mundo.', refs: ['Hch 20:7','1 Co 16:1-2','Ap 1:10'] },
      { p: '¿Cómo se ha de santificar el día de reposo?', r: 'El día de reposo se santifica descansando santamente todo el día de las obras y ocupaciones seculares, y empleando todo el tiempo en los ejercicios públicos y privados de la adoración de Dios, salvo lo necesario y lo misericordioso.', refs: ['Lv 23:3','Is 58:13-14','Mt 12:11-12'] },
      { p: '¿Cuáles son las razones añadidas al cuarto mandamiento?', r: 'Las razones son: que Dios nos concede seis días de la semana para nuestras propias ocupaciones, que se reserva para sí el día séptimo, su propio ejemplo, y su bendición sobre el día de reposo.', refs: ['Éx 20:9,11','Éx 31:17','Gn 2:3'] },
      { p: '¿Cuál es el quinto mandamiento?', r: '«Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da».', refs: ['Éx 20:12'] },
      { p: '¿Qué se requiere en el quinto mandamiento?', r: 'El quinto mandamiento requiere que conservemos el honor y cumplamos los deberes que corresponden a cada uno en sus diversas posiciones y relaciones, como superiores, inferiores o iguales.', refs: ['Ef 5:21-22','Ef 6:1-9','Ro 13:1,7'] },
      { p: '¿Qué se prohíbe en el quinto mandamiento?', r: 'El quinto mandamiento prohíbe descuidar o hacer cualquier cosa contra el honor y el deber que pertenecen a cada uno en sus diversas posiciones y relaciones.', refs: ['Mt 15:4-6','Ro 13:8','Ef 6:9'] },
      { p: '¿Cuál es la razón añadida al quinto mandamiento?', r: 'La razón añadida al quinto mandamiento es una promesa de larga vida y prosperidad (en cuanto sirva para la gloria de Dios y el bien propio) a todos los que lo guarden.', refs: ['Éx 20:12','Ef 6:2-3'] },
      { p: '¿Cuál es el sexto mandamiento?', r: '«No matarás».', refs: ['Éx 20:13'] },
      { p: '¿Qué se requiere en el sexto mandamiento?', r: 'El sexto mandamiento requiere todo esfuerzo lícito para conservar nuestra propia vida y la de los demás.', refs: ['Ef 5:28-29','1 R 18:4','Sal 82:3-4'] },
      { p: '¿Qué se prohíbe en el sexto mandamiento?', r: 'El sexto mandamiento prohíbe quitar injustamente nuestra propia vida o la del prójimo, y todo lo que a ello tienda.', refs: ['Hch 16:28','Gn 9:6','Mt 5:21-22','1 Jn 3:15'] },
      { p: '¿Cuál es el séptimo mandamiento?', r: '«No cometerás adulterio».', refs: ['Éx 20:14'] },
      { p: '¿Qué se requiere en el séptimo mandamiento?', r: 'El séptimo mandamiento requiere la conservación de nuestra propia castidad y la del prójimo, en corazón, palabra y conducta.', refs: ['1 Co 7:2-3','1 Ts 4:3-5','1 P 3:2'] },
      { p: '¿Qué se prohíbe en el séptimo mandamiento?', r: 'El séptimo mandamiento prohíbe todo pensamiento, palabra y acción impuros.', refs: ['Mt 5:28','Ef 5:3-4','Col 4:6'] },
      { p: '¿Cuál es el octavo mandamiento?', r: '«No hurtarás».', refs: ['Éx 20:15'] },
      { p: '¿Qué se requiere en el octavo mandamiento?', r: 'El octavo mandamiento requiere procurar y promover lícitamente la riqueza y el bienestar exterior nuestro y del prójimo.', refs: ['Gn 30:30','1 Ti 5:8','Lv 25:35','Ef 4:28'] },
      { p: '¿Qué se prohíbe en el octavo mandamiento?', r: 'El octavo mandamiento prohíbe todo lo que injustamente impida o menoscabe la riqueza o el bienestar exterior nuestro o del prójimo.', refs: ['Pr 21:6','1 Ts 4:6','Ef 4:28'] },
      { p: '¿Cuál es el noveno mandamiento?', r: '«No hablarás contra tu prójimo falso testimonio».', refs: ['Éx 20:16'] },
      { p: '¿Qué se requiere en el noveno mandamiento?', r: 'El noveno mandamiento requiere mantener y promover la verdad entre los hombres, y el buen nombre nuestro y del prójimo, especialmente al dar testimonio.', refs: ['Zac 8:16','3 Jn 12','Pr 14:5,25'] },
      { p: '¿Qué se prohíbe en el noveno mandamiento?', r: 'El noveno mandamiento prohíbe todo lo que perjudique la verdad, o el buen nombre nuestro o del prójimo.', refs: ['1 S 17:28','Lv 19:16','Sal 15:3'] },
      { p: '¿Cuál es el décimo mandamiento?', r: '«No codiciarás la casa de tu prójimo, ni su mujer, ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo».', refs: ['Éx 20:17'] },
      { p: '¿Qué se requiere en el décimo mandamiento?', r: 'El décimo mandamiento requiere plena satisfacción con nuestra propia condición, y una disposición recta y caritativa hacia el prójimo y todo lo que es suyo.', refs: ['He 13:5','1 Ti 6:6','Ro 12:15','1 Co 13:4-7'] },
      { p: '¿Qué se prohíbe en el décimo mandamiento?', r: 'El décimo mandamiento prohíbe todo descontento con nuestra propia condición, la envidia o el pesar por el bien del prójimo, y todo afecto o deseo desordenado hacia lo que es suyo.', refs: ['1 Co 10:10','Stg 3:14-16','Gá 5:26','Col 3:5'] },
      { p: '¿Puede algún hombre guardar perfectamente los mandamientos de Dios?', r: 'Ningún mero hombre, desde la caída, es capaz en esta vida de guardar perfectamente los mandamientos de Dios, sino que los quebranta cada día en pensamiento, palabra y obra.', refs: ['Ec 7:20','1 Jn 1:8,10','Gá 5:17','Stg 3:2'] },
      { p: '¿Son todas las transgresiones de la ley igualmente odiosas?', r: 'Algunos pecados en sí mismos, y por razón de diversas agravantes, son más odiosos a los ojos de Dios que otros.', refs: ['Jn 19:11','Ez 8:6,13,15','1 Jn 5:16'] },
      { p: '¿Qué merece todo pecado?', r: 'Todo pecado merece la ira y la maldición de Dios, tanto en esta vida como en la venidera.', refs: ['Ef 5:6','Gá 3:10','Lm 3:39','Mt 25:41'] },
      { p: '¿Qué requiere Dios de nosotros para que escapemos de su ira y maldición debidas por el pecado?', r: 'Para escapar de la ira y maldición de Dios debidas por el pecado, Dios requiere de nosotros fe en Jesucristo y arrepentimiento para vida, junto con el uso diligente de todos los medios externos por los cuales Cristo nos comunica los beneficios de la redención.', refs: ['Hch 20:21','Hch 16:30-31','Pr 2:1-5'] },
      { p: '¿Qué es la fe en Jesucristo?', r: 'La fe en Jesucristo es una gracia salvadora por la cual recibimos a Cristo y descansamos solo en él para la salvación, tal como nos es ofrecido en el evangelio.', refs: ['He 10:39','Jn 1:12','Fil 3:9','Gá 2:16'] },
      { p: '¿Qué es el arrepentimiento para vida?', r: 'El arrepentimiento para vida es una gracia salvadora por la cual el pecador, con verdadero sentido de su pecado y con la aprehensión de la misericordia de Dios en Cristo, se vuelve de todo pecado a Dios con dolor y aborrecimiento, con el firme propósito y empeño de una nueva obediencia.', refs: ['Hch 11:18','Jl 2:12-13','2 Co 7:10-11','Ez 36:31'] },
      { p: '¿Cuáles son los medios externos por los cuales Cristo nos comunica los beneficios de la redención?', r: 'Los medios externos y ordinarios por los cuales Cristo nos comunica los beneficios de la redención son sus ordenanzas, especialmente la Palabra, el Bautismo, la Cena del Señor y la oración; todos los cuales son hechos eficaces para los elegidos para su salvación.', refs: ['Mt 28:19-20','Hch 2:41-42'] },
      { p: '¿Cómo es hecha eficaz la Palabra para la salvación?', r: 'El Espíritu de Dios hace de la lectura, y especialmente de la predicación de la Palabra, un medio eficaz para convencer y convertir a los pecadores, y para edificarlos en santidad y consuelo, por la fe, para salvación.', refs: ['Neh 8:8','1 Co 14:24-25','Hch 26:18','Ro 1:16','1 Ts 1:6'] },
      { p: '¿Cómo se ha de leer y oír la Palabra para que sea eficaz para la salvación?', r: 'Para que la Palabra sea eficaz para la salvación, debemos atender a ella con diligencia, preparación y oración; recibirla con fe y amor, atesorarla en nuestro corazón y practicarla en nuestra vida.', refs: ['Pr 8:34','1 P 2:1-2','Sal 119:11','He 4:2','Stg 1:22-25'] },
      { p: '¿Cómo llegan a ser el Bautismo y la Cena del Señor medios eficaces de salvación?', r: 'El Bautismo y la Cena del Señor llegan a ser medios eficaces de salvación, no por virtud alguna en ellos mismos ni en quien los administra, sino solo por la bendición de Cristo y la obra de su Espíritu en los que por fe los reciben.', refs: ['1 P 3:21','1 Co 3:6-7','1 Co 12:13'] },
      { p: '¿Qué es el Bautismo?', r: 'El Bautismo es una ordenanza del Nuevo Testamento, instituida por Jesucristo, señal de la comunión del creyente con Cristo en su muerte y resurrección, de estar injertado en él, de la remisión de pecados y de su entrega a Dios por Jesucristo para andar en novedad de vida.', refs: ['Mt 28:19','Ro 6:3-5','Gá 3:27','Col 2:12'] },
      { p: '¿A quién se ha de administrar el Bautismo?', r: 'El Bautismo se ha de administrar a todos aquellos que realmente profesan arrepentimiento para con Dios y fe en nuestro Señor Jesucristo, y a ningún otro.', refs: ['Hch 2:38','Hch 8:12,36-37','Mr 16:16'] },
      { p: '¿Han de bautizarse los pequeños hijos de los creyentes que profesan la fe?', r: 'Los pequeños hijos de los creyentes que profesan la fe no han de ser bautizados, porque no hay ni mandato ni ejemplo en las Santas Escrituras para su bautismo.', refs: ['Pr 30:6','Mr 16:16','Hch 2:38'] },
      { p: '¿Cómo se administra correctamente el Bautismo?', r: 'El Bautismo se administra correctamente por inmersión, sumergiendo todo el cuerpo de la persona en agua, en el nombre del Padre, del Hijo y del Espíritu Santo.', refs: ['Mt 3:16','Jn 3:23','Hch 8:38-39','Ro 6:4','Col 2:12'] },
      { p: '¿Cuál es el deber de los que son bautizados correctamente?', r: 'El deber de los que son bautizados correctamente es entregarse a alguna iglesia particular y ordenada de Jesucristo, para andar en todos sus mandamientos y ordenanzas de manera irreprensible.', refs: ['Hch 2:41-42,47','Hch 9:26','1 P 2:5','He 10:25'] },
      { p: '¿Qué es la Cena del Señor?', r: 'La Cena del Señor es una ordenanza del Nuevo Testamento, instituida por Jesucristo; en ella, al dar y recibir pan y vino conforme a su designación, se anuncia su muerte, y los que reciben dignamente participan por la fe, no de manera carnal sino espiritual, de su cuerpo y su sangre con todos sus beneficios, para su alimento y crecimiento en gracia.', refs: ['1 Co 11:23-26','1 Co 10:16'] },
      { p: '¿Qué se requiere para recibir dignamente la Cena del Señor?', r: 'Se requiere de los que reciben la Cena del Señor que se examinen sobre su conocimiento para discernir el cuerpo del Señor, su fe para alimentarse de él, su arrepentimiento, amor y nueva obediencia; no sea que, viniendo indignamente, coman y beban juicio para sí.', refs: ['1 Co 11:28-29','2 Co 13:5','1 Co 11:31','1 Co 5:8'] },
      { p: '¿Qué es la oración?', r: 'La oración es un ofrecimiento de nuestros deseos a Dios, por cosas conformes a su voluntad, en el nombre de Cristo, con confesión de nuestros pecados y agradecido reconocimiento de sus misericordias.', refs: ['Sal 62:8','1 Jn 5:14','Jn 16:23','Sal 32:5-6','Fil 4:6'] },
      { p: '¿Qué regla nos ha dado Dios para dirigirnos en la oración?', r: 'Toda la Palabra de Dios es útil para dirigirnos en la oración; pero la regla especial de dirección es aquella oración que Cristo enseñó a sus discípulos, comúnmente llamada el Padrenuestro.', refs: ['2 Ti 3:16-17','1 Jn 5:14','Mt 6:9-13'] },
      { p: '¿Qué nos enseña el prefacio del Padrenuestro?', r: 'El prefacio, «Padre nuestro que estás en los cielos», nos enseña a acercarnos a Dios con toda santa reverencia y confianza, como hijos a un padre capaz y dispuesto a ayudarnos, y que debemos orar con y por los demás.', refs: ['Mt 6:9','Ro 8:15','Lc 11:13','1 Ti 2:1-2'] },
      { p: '¿Qué pedimos en la primera petición?', r: 'En la primera petición, «Santificado sea tu nombre», pedimos que Dios nos capacite a nosotros y a todos para glorificarle en todo aquello por lo cual él se da a conocer, y que disponga todas las cosas para su propia gloria.', refs: ['Sal 67:2-3','Ro 11:36','Ap 4:11'] },
      { p: '¿Qué pedimos en la segunda petición?', r: 'En la segunda petición, «Venga tu reino», pedimos que el reino de Satanás sea destruido, que el reino de la gracia se extienda, que nosotros y otros seamos traídos a él y guardados en él, y que el reino de la gloria sea apresurado.', refs: ['Sal 68:1,18','Ap 12:10-11','2 Ts 3:1','Ro 10:1','Ap 22:20'] },
      { p: '¿Qué pedimos en la tercera petición?', r: 'En la tercera petición, «Hágase tu voluntad, como en el cielo, así también en la tierra», pedimos que Dios, por su gracia, nos haga capaces y dispuestos a conocer, obedecer y someternos a su voluntad en todo, como lo hacen los ángeles en el cielo.', refs: ['Sal 103:20-21','Mt 26:39','Hch 21:14','Sal 119:34-36'] },
      { p: '¿Qué pedimos en la cuarta petición?', r: 'En la cuarta petición, «El pan nuestro de cada día, dánoslo hoy», pedimos que, de la libre dádiva de Dios, recibamos una porción suficiente de las cosas buenas de esta vida, y gocemos de su bendición con ellas.', refs: ['Pr 30:8-9','Mt 6:31-33','1 Ti 4:4-5'] },
      { p: '¿Qué pedimos en la quinta petición?', r: 'En la quinta petición, «Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores», pedimos que Dios, por causa de Cristo, nos perdone gratuitamente todos nuestros pecados; lo cual nos anima a pedir tanto más cuanto que, por su gracia, podemos de corazón perdonar a otros.', refs: ['Sal 51:1-2','Dn 9:17-19','Mt 6:14-15','Mt 18:35'] },
      { p: '¿Qué pedimos en la sexta petición?', r: 'En la sexta petición, «No nos metas en tentación, mas líbranos del mal», pedimos que Dios nos guarde de ser tentados a pecar, o nos sostenga y libre cuando somos tentados.', refs: ['Mt 26:41','2 Co 12:7-8','1 Co 10:13','Jn 17:15'] },
      { p: '¿Qué nos enseña la conclusión del Padrenuestro?', r: 'La conclusión, «Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén», nos enseña a tomar de solo Dios el aliento para orar, y a alabarle atribuyéndole el reino, el poder y la gloria; y en testimonio de nuestro deseo y seguridad de ser oídos, decimos: Amén.', refs: ['Dn 9:18-19','1 Cr 29:11-13','1 Co 14:16','Ap 22:20'] }
    ]
  },

  collins1680: {
    titulo: 'Catecismo de Hércules Collins (1680)',
    sub: 'Collins · 1680',
    nota: 'El «Catecismo Ortodoxo» de Hércules Collins, pastor bautista particular de Londres y firmante de la Confesión de 1689. Es una adaptación bautista del Catecismo de Heidelberg —cálida y cristocéntrica— que Collins hizo para mostrar la comunión de los bautistas con la fe reformada histórica, ajustando lo tocante al bautismo. Sigue la estructura de Heidelberg: la miseria, la liberación y la gratitud.',
    fuente: 'Orthodox Catechism de Hércules Collins (1680) · texto de dominio público. Toca una referencia para leerla en la Biblia.',
    preguntas: [
      { p: '¿Cuál es tu único consuelo en la vida y en la muerte?', r: 'Que yo, en cuerpo y alma, tanto en la vida como en la muerte, no me pertenezco a mí mismo, sino a mi fiel Salvador Jesucristo, quien con su preciosa sangre ha pagado plenamente por todos mis pecados y me ha librado de todo el poder del diablo; y de tal manera me guarda, que sin la voluntad de mi Padre celestial ni un solo cabello puede caer de mi cabeza; antes bien, todas las cosas han de servir para mi salvación. Por lo cual también, por su Espíritu Santo, me asegura la vida eterna y me hace de corazón dispuesto y pronto para vivir en adelante para él.', refs: ['Ro 14:7-9','1 Co 6:19-20','1 P 1:18-19','1 Jn 1:7','Jn 8:34-36','He 2:14-15','Jn 6:39','Mt 10:29-30','Ro 8:28','2 Co 1:21-22','Ef 1:13-14','Ro 8:14'] },
      { p: '¿Cuántas cosas te es necesario saber para que, gozando de este consuelo, vivas y mueras bienaventuradamente?', r: 'Tres: la primera, cuán grandes son mi pecado y mi miseria; la segunda, cómo soy librado de todos mis pecados y miserias; y la tercera, cómo he de ser agradecido a Dios por tal liberación.', refs: ['Mt 11:28-30','Jn 17:3','Ro 3:19','Ef 5:8-10','1 P 2:9-12'] },
      { p: '¿De dónde conoces tu miseria?', r: 'De la ley de Dios.', refs: ['Ro 3:20','Ro 7:7'] },
      { p: '¿Qué exige de nosotros la ley de Dios?', r: 'Cristo nos lo enseña en suma: «Amarás al Señor tu Dios con todo tu corazón, con toda tu alma, con todas tus fuerzas y con toda tu mente; y a tu prójimo como a ti mismo».', refs: ['Mt 22:37-40','Dt 6:5','Lv 19:18'] },
      { p: '¿Puedes cumplir todo esto perfectamente?', r: 'No; porque por naturaleza estoy inclinado a aborrecer a Dios y a mi prójimo.', refs: ['Ro 3:10,23','1 Jn 1:8,10','Ro 8:7','Ef 2:3','Tit 3:3'] },
      { p: '¿Creó, pues, Dios al hombre tan malo y perverso?', r: 'No; sino que Dios creó al hombre bueno y a su imagen, esto es, en verdadera justicia y santidad, para que conociera rectamente a Dios su Creador, le amara de corazón y viviera con él en eterna bienaventuranza, para alabarle y glorificarle.', refs: ['Gn 1:26-27,31','Ef 4:24','Col 3:10'] },
      { p: '¿De dónde procede, entonces, esta naturaleza corrompida del hombre?', r: 'De la caída y desobediencia de nuestros primeros padres, Adán y Eva, en el paraíso; de donde nuestra naturaleza quedó tan corrompida que todos somos concebidos y nacidos en pecado.', refs: ['Gn 3:6','Ro 5:12,18-19','Sal 51:5'] },
      { p: '¿Pero estamos tan corrompidos que somos del todo incapaces de hacer bien alguno e inclinados a todo mal?', r: 'Sí, a menos que seamos regenerados por el Espíritu de Dios.', refs: ['Gn 6:5','Jn 3:3,5-6','Ro 7:18','2 Co 3:5'] },
      { p: '¿No es, entonces, Dios injusto al exigir en su ley del hombre lo que este no puede cumplir?', r: 'No; porque Dios creó al hombre capaz de cumplirla; pero el hombre, por instigación del diablo y por su propia rebeldía, se privó a sí mismo y a toda su descendencia de estos dones.', refs: ['Ec 7:29','Ef 4:24','Ro 5:12'] },
      { p: '¿Dejará Dios sin castigo tal desobediencia y apostasía?', r: 'De ninguna manera; antes se aíra terriblemente contra el pecado, tanto el de nacimiento como el actual, y quiere castigarlo con justo juicio en el tiempo y en la eternidad, como ha declarado: «Maldito todo aquel que no permaneciere en todas las cosas escritas en el libro de la ley, para hacerlas».', refs: ['Éx 34:7','Dt 27:26','Gá 3:10','Ro 1:18','He 9:27'] },
      { p: '¿No es Dios, entonces, también misericordioso?', r: 'Sí, Dios es ciertamente misericordioso, pero también es justo; por tanto, su justicia requiere que el pecado, cometido contra la majestad soberana de Dios, sea también castigado con la suma pena, esto es, con la muerte eterna del cuerpo y del alma.', refs: ['Éx 34:6-7','Sal 103:8-9','Éx 20:5','Dt 32:4','2 Co 6:14-16'] },
      { p: 'Puesto que por el justo juicio de Dios merecemos castigo temporal y eterno, ¿cómo podemos escapar de él y ser de nuevo recibidos en gracia?', r: 'Dios quiere que su justicia sea satisfecha; por tanto, es necesario que satisfagamos plenamente, sea por nosotros mismos, sea por otro.', refs: ['Éx 20:5','Ez 18:4','Ro 8:3-4'] },
      { p: '¿Podemos nosotros mismos satisfacer?', r: 'De ninguna manera; antes bien, cada día aumentamos nuestra deuda.', refs: ['Job 9:2-3','Mt 6:12','Sal 130:3'] },
      { p: '¿Puede hallarse alguna criatura que, siendo mera criatura, satisfaga por nosotros?', r: 'Ninguna; porque, primero, Dios no quiere castigar en otra criatura la culpa que el hombre cometió; y además, ninguna mera criatura puede soportar la carga de la ira eterna de Dios contra el pecado y librar de ella a otros.', refs: ['He 2:14-18','Sal 130:3','Nah 1:6'] },
      { p: '¿Qué clase de mediador y libertador, entonces, debemos buscar?', r: 'Uno que sea verdadero hombre y perfectamente justo, y a la vez más poderoso que todas las criaturas, esto es, que sea también verdadero Dios.', refs: ['1 Co 15:21','Jer 33:16','Is 7:14','Ro 9:5'] },
      { p: '¿Por qué debe ser verdadero hombre y perfectamente justo?', r: 'Porque la justicia de Dios requiere que la misma naturaleza humana que pecó pague por el pecado; y quien es él mismo pecador no puede pagar por otros.', refs: ['Ro 5:12,15','1 P 3:18','He 7:26-27'] },
      { p: '¿Por qué debe ser a la vez verdadero Dios?', r: 'Para que, por el poder de su divinidad, pudiese soportar en su naturaleza humana la carga de la ira de Dios, y así adquirir y devolvernos la justicia y la vida.', refs: ['Is 53:8','Hch 2:24','Jn 3:16'] },
      { p: '¿Quién es ese mediador que es a la vez verdadero Dios y verdadero hombre justo?', r: 'Nuestro Señor Jesucristo, que nos fue hecho por Dios sabiduría, justificación, santificación y redención.', refs: ['1 Ti 2:5','1 Co 1:30','Mt 1:23'] },
      { p: '¿De dónde sabes esto?', r: 'Del santo evangelio, que Dios mismo reveló primeramente en el paraíso, luego proclamó por los patriarcas y profetas, prefiguró por los sacrificios y demás ceremonias de la ley, y finalmente cumplió por su unigénito Hijo.', refs: ['Gn 3:15','Ro 1:2','He 1:1','Gá 4:4','Hch 10:43'] },
      { p: '¿Son, entonces, salvos por Cristo todos los hombres, como perecieron todos por Adán?', r: 'No; sino solo aquellos que por verdadera fe son injertados en él y reciben todos sus beneficios.', refs: ['Mt 7:14','Jn 1:12','Ro 11:20','He 4:2-3'] },
      { p: '¿Qué es la verdadera fe?', r: 'No es solo un conocimiento cierto por el cual tengo por verdadero todo lo que Dios nos ha revelado en su Palabra, sino también una firme confianza que el Espíritu Santo obra en mi corazón por el evangelio: que no solo a otros, sino también a mí, me son dados por Dios, por pura gracia y solo por los méritos de Cristo, el perdón de los pecados, la justicia eterna y la salvación.', refs: ['He 11:1,3','Ro 4:16-18','Ro 1:16','Gá 2:20','Ef 2:8'] },
      { p: '¿Qué es, pues, necesario que el cristiano crea?', r: 'Todo lo que se nos promete en el evangelio, que los artículos de nuestra fe católica e indubitable nos enseñan en suma.', refs: ['Jn 20:31','Mt 28:19'] },
      { p: '¿Cuáles son estos artículos?', r: 'Creo en Dios Padre todopoderoso, Creador del cielo y de la tierra. Y en Jesucristo, su único Hijo, nuestro Señor; que fue concebido por el Espíritu Santo, nació de la virgen María; padeció bajo el poder de Poncio Pilato, fue crucificado, muerto y sepultado; descendió a los infiernos; al tercer día resucitó de entre los muertos; subió a los cielos, y está sentado a la diestra de Dios Padre todopoderoso; y desde allí ha de venir a juzgar a los vivos y a los muertos. Creo en el Espíritu Santo; la santa iglesia universal; la comunión de los santos; el perdón de los pecados; la resurrección del cuerpo; y la vida eterna. Amén.', refs: ['Mt 28:19'] },
      { p: '¿Cómo se dividen estos artículos?', r: 'En tres partes: la primera, de Dios Padre y de nuestra creación; la segunda, de Dios Hijo y de nuestra redención; la tercera, de Dios Espíritu Santo y de nuestra santificación.', refs: ['1 P 1:2'] },
      { p: 'Siendo un solo Dios, ¿por qué nombras tres: el Padre, el Hijo y el Espíritu Santo?', r: 'Porque así se ha revelado Dios en su Palabra: que estas tres personas distintas son el único, verdadero y eterno Dios.', refs: ['Dt 6:4','Mt 28:19','2 Co 13:14','1 Jn 5:7'] },
      { p: '¿Qué crees cuando dices: «Creo en Dios Padre todopoderoso, Creador del cielo y de la tierra»?', r: 'Que el eterno Padre de nuestro Señor Jesucristo, que de la nada creó el cielo y la tierra con todo lo que hay en ellos, y los sostiene y gobierna por su eterno consejo y providencia, es, por causa de Cristo su Hijo, mi Dios y mi Padre; en quien confío de tal modo que no dudo de que proveerá para todas mis necesidades de cuerpo y alma, y que todo mal que me envíe en este valle de lágrimas lo tornará para mi bien, pues puede hacerlo como Dios todopoderoso, y quiere hacerlo como Padre fiel.', refs: ['Gn 1:1','Sal 33:6','Mt 6:26','Ro 8:28','Sal 55:22','Ro 8:15'] },
      { p: '¿Qué entiendes por la providencia de Dios?', r: 'El poder de Dios, todopoderoso y presente en todas partes, por el cual sostiene y gobierna, como con su mano, el cielo, la tierra y todas las criaturas; de modo que las plantas y la lluvia, los años fértiles y estériles, la salud y la enfermedad, la riqueza y la pobreza, todo nos viene, no por acaso, sino de su mano paternal.', refs: ['Hch 17:25-28','He 1:3','Pr 16:33','Sal 103:19','Mt 10:29-30'] },
      { p: '¿De qué nos aprovecha conocer la creación y la providencia de Dios?', r: 'Que en toda adversidad seamos pacientes, en la prosperidad agradecidos, y para lo por venir tengamos plena confianza en nuestro fiel Dios y Padre, de que ninguna criatura nos apartará de su amor, pues todas están de tal modo en su mano, que sin su voluntad no pueden moverse.', refs: ['Ro 5:3-4','Job 1:21-22','Ro 8:38-39','Job 1:12'] },
      { p: '¿Por qué se llama al Hijo de Dios «Jesús», es decir, Salvador?', r: 'Porque él nos salva de nuestros pecados, y porque en ningún otro se ha de buscar ni hallar salvación alguna.', refs: ['Mt 1:21','Hch 4:12','Lc 2:11'] },
      { p: '¿Creen, entonces, en el único Salvador Jesús los que buscan su salvación en los santos, en sí mismos o en otra parte?', r: 'No; antes bien, aunque de palabra se glorían en él, con los hechos niegan al único Salvador Jesús; porque, o Jesús no es un Salvador perfecto, o los que por verdadera fe le reciben tienen en él todo lo necesario para su salvación.', refs: ['1 Co 1:13,30-31','Gá 5:4','He 12:2'] },
      { p: '¿Por qué se llama «Cristo», es decir, Ungido?', r: 'Porque fue ordenado por Dios Padre y ungido con el Espíritu Santo para ser nuestro supremo Profeta, que nos revela el consejo de Dios acerca de nuestra redención; nuestro único Sumo Sacerdote, que con el único sacrificio de su cuerpo nos redimió y sin cesar intercede por nosotros; y nuestro eterno Rey, que nos gobierna con su Palabra y su Espíritu, y nos ampara en la salvación adquirida.', refs: ['Sal 45:7','He 1:9','Dt 18:15','Sal 110:4','Mt 28:18'] },
      { p: '¿Por qué eres tú llamado cristiano?', r: 'Porque por la fe soy miembro de Cristo y participante de su unción; para que confiese su nombre, me presente a él como sacrificio vivo de gratitud, combata en esta vida contra el pecado y el diablo con conciencia libre, y después reine con él eternamente sobre todas las criaturas.', refs: ['Hch 11:26','1 Jn 2:27','Ro 12:1','1 P 2:9','Ap 5:10'] },
      { p: '¿Por qué se llama «único Hijo» de Dios, siendo también nosotros hijos de Dios?', r: 'Porque solo Cristo es el eterno Hijo natural de Dios; mientras que nosotros somos hijos de Dios adoptados por gracia, por causa de él.', refs: ['Jn 1:14,18','Ro 8:15-17','Ef 1:5-6'] },
      { p: '¿Por qué le llamas «nuestro Señor»?', r: 'Porque, no con oro ni plata, sino con su preciosa sangre nos ha redimido y comprado, en cuerpo y alma, de todos nuestros pecados y de todo el poder del diablo, para hacernos suyos.', refs: ['1 P 1:18-19','1 Co 6:20','Col 1:13-14'] },
      { p: '¿Qué crees cuando dices: «fue concebido por el Espíritu Santo, nació de la virgen María»?', r: 'Que el eterno Hijo de Dios, que es y permanece verdadero y eterno Dios, tomó verdadera naturaleza humana, de la carne y sangre de la virgen María, por obra del Espíritu Santo; para ser también verdadera simiente de David, semejante a sus hermanos en todo, salvo en el pecado.', refs: ['Jn 1:1','Lc 1:35','Ro 1:3','He 2:17','He 4:15'] },
      { p: '¿Qué provecho recibes de la santa concepción y nacimiento de Cristo?', r: 'Que es nuestro mediador, y que con su inocencia y perfecta santidad cubre, delante de Dios, mi pecado, en el cual fui concebido y nacido.', refs: ['He 7:26-27','1 P 1:18-19','1 Co 1:30-31','Ro 8:3-4'] },
      { p: '¿Qué entiendes por la palabra «padeció»?', r: 'Que durante todo el tiempo que vivió en la tierra, y especialmente al fin de su vida, llevó en cuerpo y alma la ira de Dios contra el pecado de todo el género humano; para que, con su pasión, como único sacrificio expiatorio, librara nuestro cuerpo y alma de la condenación eterna, y nos adquiriera la gracia de Dios, la justicia y la vida eterna.', refs: ['Is 53:4-5,12','1 P 2:24','1 Jn 2:2','Ro 3:25-26'] },
      { p: '¿Por qué padeció «bajo el poder de Poncio Pilato», como juez?', r: 'Para que, siendo inocente, fuera condenado por un juez terrenal, y así nos librara del severo juicio de Dios que había de caer sobre nosotros.', refs: ['Lc 23:13-24','Jn 19:4','2 Co 5:21','Gá 3:13'] },
      { p: '¿Hay algo más en que fuera «crucificado» y no muriera de otra manera?', r: 'Sí; pues por ello estoy seguro de que él tomó sobre sí la maldición que pesaba sobre mí, porque la muerte de cruz era maldita de Dios.', refs: ['Gá 3:13','Dt 21:23'] },
      { p: '¿Por qué fue necesario que Cristo «muriera»?', r: 'Porque la justicia y la verdad de Dios exigían que no se hiciera satisfacción por nuestros pecados sino por la muerte del Hijo de Dios.', refs: ['Gn 2:17','He 2:9,14-15','Ro 8:3-4'] },
      { p: '¿Por qué fue «sepultado»?', r: 'Para dar testimonio de que verdaderamente había muerto.', refs: ['Is 53:9','Jn 19:38-42','Hch 13:29','1 Co 15:3-4'] },
      { p: 'Si Cristo murió por nosotros, ¿por qué hemos de morir también nosotros?', r: 'Nuestra muerte no es paga por nuestros pecados, sino solo un morir al pecado y una entrada a la vida eterna.', refs: ['Fil 1:23','Jn 5:24','Ro 7:24-25'] },
      { p: '¿Qué más provecho recibimos del sacrificio y muerte de Cristo en la cruz?', r: 'Que por su virtud nuestro viejo hombre es con él crucificado, muerto y sepultado, para que las malas concupiscencias de la carne no reinen ya en nosotros, sino que nos ofrezcamos a él en sacrificio de gratitud.', refs: ['Ro 6:6-12','Col 3:5','Ro 12:1'] },
      { p: '¿Por qué se añade: «descendió a los infiernos»?', r: 'Para que en mis mayores angustias esté seguro de que mi Señor Jesucristo, con las angustias y tormentos inexpresables que padeció en su alma, especialmente en la cruz, me ha librado de las angustias y el tormento del infierno.', refs: ['Is 53:10','Mt 26:38','Mt 27:46','He 5:7'] },
      { p: '¿Qué provecho recibimos de la «resurrección» de Cristo?', r: 'Primero, que con su resurrección venció a la muerte, para hacernos partícipes de la justicia que con su muerte nos adquirió. Segundo, que por su poder somos también nosotros ya resucitados a una vida nueva. Tercero, que la resurrección de Cristo es para nosotros prenda segura de nuestra gloriosa resurrección.', refs: ['Ro 4:25','1 P 1:3','Ro 6:4','1 Co 15:20-21'] },
      { p: '¿Qué entiendes por «subió a los cielos»?', r: 'Que Cristo, a la vista de sus discípulos, fue tomado de la tierra al cielo, y allí permanece en favor nuestro, hasta que vuelva a juzgar a los vivos y a los muertos.', refs: ['Hch 1:9-11','Mr 16:19','He 9:24','Ro 8:34'] },
      { p: '¿No está, entonces, Cristo con nosotros hasta el fin del mundo, como nos ha prometido?', r: 'Cristo es verdadero hombre y verdadero Dios: según su naturaleza humana ya no está en la tierra; pero según su divinidad, majestad, gracia y Espíritu, nunca se aparta de nosotros.', refs: ['Mt 28:20','Jn 16:28','He 8:4','Jn 14:18'] },
      { p: '¿Qué provecho nos trae la ascensión de Cristo?', r: 'Primero, que es nuestro abogado en el cielo ante su Padre. Segundo, que tenemos nuestra carne en el cielo como prenda segura de que él, como cabeza, nos llevará también a nosotros, sus miembros, hacia sí. Tercero, que nos envía su Espíritu como prenda recíproca, por cuyo poder buscamos las cosas de arriba, donde Cristo está sentado a la diestra de Dios, y no las de la tierra.', refs: ['1 Jn 2:1','Jn 14:2-3','Jn 16:7','Col 3:1-4'] },
      { p: '¿Qué nos aprovecha esta gloria de Cristo, nuestra cabeza?', r: 'Primero, que por su Espíritu Santo derrama los dones celestiales sobre nosotros, sus miembros. Segundo, que con su poder nos defiende y conserva contra todos los enemigos.', refs: ['Ef 4:8','Sal 110:1-2','Jn 10:28'] },
      { p: '¿Qué te consuela la vuelta de Cristo «a juzgar a los vivos y a los muertos»?', r: 'Que en toda tribulación y persecución espero como juez, con la cabeza en alto, al mismo que antes se ofreció por mí ante el juicio de Dios y quitó toda maldición de sobre mí; el cual arrojará a sus enemigos y los míos a la condenación eterna, pero a mí, con todos los elegidos, me llevará consigo al gozo y la gloria celestial.', refs: ['Lc 21:28','Fil 3:20-21','2 Ts 1:6-10','Mt 25:34,41'] },
      { p: '¿Qué crees del «Espíritu Santo»?', r: 'Primero, que es, juntamente con el Padre y el Hijo, verdadero y eterno Dios. Segundo, que también me es dado a mí, para hacerme, por verdadera fe, partícipe de Cristo y de todos sus beneficios, consolarme y permanecer conmigo para siempre.', refs: ['Gn 1:2','1 Co 6:19','Gá 4:6','Jn 14:16-17','1 P 1:2'] },
      { p: '¿Qué crees de la «santa iglesia universal»?', r: 'Que el Hijo de Dios, de todo el género humano, desde el principio del mundo hasta el fin, reúne, defiende y conserva para sí, por su Espíritu y su Palabra, en la unidad de la verdadera fe, una comunidad elegida para la vida eterna; y que yo soy y por siempre seré miembro vivo de ella.', refs: ['Jn 10:11','Hch 20:28','Ef 4:3-6','Sal 71:18','1 Jn 2:19'] },
      { p: '¿Qué entiendes por la «comunión de los santos»?', r: 'Primero, que todos los creyentes, como miembros, tienen comunión con el Señor Cristo y participan de todos sus tesoros y dones. Segundo, que cada uno debe emplear sus dones, con prontitud y alegría, para provecho y salvación de los demás miembros.', refs: ['1 Jn 1:3','1 Co 12:12-13','1 Co 6:17','Ro 12:4-8'] },
      { p: '¿Qué crees del «perdón de los pecados»?', r: 'Que Dios, por causa de la satisfacción de Cristo, no quiere acordarse más de ninguno de mis pecados, ni de la corrupción con la que he de luchar toda mi vida; sino que por gracia me otorga la justicia de Cristo, para que jamás sea condenado.', refs: ['1 Jn 2:2','Jer 31:34','2 Co 5:19,21','Ro 8:1'] },
      { p: '¿Qué consuelo te da «la resurrección del cuerpo»?', r: 'Que no solo mi alma, después de esta vida, será llevada inmediatamente a Cristo, su cabeza; sino también que esta misma carne mía, resucitada por el poder de Cristo, será unida de nuevo a mi alma y hecha semejante al cuerpo glorioso de Cristo.', refs: ['Lc 23:43','Fil 1:21-23','Job 19:25-26','1 Co 15:53-54','Fil 3:21'] },
      { p: '¿Qué consuelo recibes del artículo de «la vida eterna»?', r: 'Que, sintiendo ya ahora en mi corazón el principio del gozo eterno, poseeré después de esta vida perfecta bienaventuranza, cual ojo no vio, ni oído oyó, ni ha subido a corazón de hombre, para alabar a Dios en ella eternamente.', refs: ['2 Co 5:2-3','1 Co 2:9','Jn 17:3'] },
      { p: '¿De qué te sirve ahora creer todo esto?', r: 'Que soy justo delante de Dios en Cristo, y heredero de la vida eterna.', refs: ['Hab 2:4','Ro 1:17','Jn 3:36'] },
      { p: '¿Cómo eres justo delante de Dios?', r: 'Solo por verdadera fe en Jesucristo; de modo que, aunque mi conciencia me acuse de que he pecado gravemente contra todos los mandamientos de Dios y de que todavía estoy inclinado a todo mal, sin embargo, Dios, sin ningún mérito mío, por sola gracia, me imputa y me otorga la perfecta satisfacción, justicia y santidad de Cristo, como si yo nunca hubiera tenido ni cometido pecado alguno, y como si yo mismo hubiera cumplido toda la obediencia que Cristo cumplió por mí; con tal que reciba tales beneficios con corazón creyente.', refs: ['Ro 3:21-25','Ro 4:3-5','2 Co 5:19,21','1 Jn 2:1-2','Ef 2:8-9'] },
      { p: '¿Por qué dices que eres justo solo por la fe?', r: 'No porque yo sea agradable a Dios por el mérito de mi fe; sino porque solo la satisfacción, justicia y santidad de Cristo son mi justicia delante de Dios, y no puedo recibirla ni hacerla mía de otra manera que solo por la fe.', refs: ['1 Co 1:30-31','Ro 10:10','1 Jn 5:10-12'] },
      { p: '¿Por qué no pueden nuestras buenas obras ser la justicia delante de Dios, o parte de ella?', r: 'Porque la justicia que ha de subsistir ante el juicio de Dios debe ser del todo perfecta y conforme en todo a la ley divina; y aun nuestras mejores obras en esta vida son todas imperfectas y contaminadas de pecado.', refs: ['Gá 3:10','Dt 27:26','Is 64:6'] },
      { p: '¿No merecen nada nuestras buenas obras, que Dios quiere recompensar en esta vida y en la venidera?', r: 'Esa recompensa no se da por mérito, sino por gracia.', refs: ['Lc 17:10','He 11:6','2 Ti 4:7-8'] },
      { p: '¿No hace esta doctrina a los hombres descuidados y profanos?', r: 'No; porque es imposible que quienes están injertados en Cristo por verdadera fe no produzcan frutos de gratitud.', refs: ['Mt 7:18','Jn 15:5','Lc 6:43-45'] },
      { p: 'Puesto que solo la fe nos hace partícipes de Cristo y de todos sus beneficios, ¿de dónde procede tal fe?', r: 'Del Espíritu Santo, que la enciende en nuestros corazones por la predicación del santo evangelio, y la confirma por el uso de los sacramentos.', refs: ['Ef 2:8','Ro 10:17','Mt 28:19','1 P 1:22-23'] },
      { p: '¿Qué son los sacramentos?', r: 'Son signos y sellos santos y visibles, instituidos por Dios para que, por su uso, nos declare y selle más plenamente la promesa del evangelio: que por el único sacrificio de Cristo consumado en la cruz nos otorga gratuitamente el perdón de los pecados y la vida eterna.', refs: ['Gn 17:11','Ro 4:11','Dt 30:6','He 9:8-9'] },
      { p: '¿Están ordenados tanto la Palabra como los sacramentos para dirigir nuestra fe al sacrificio de Cristo en la cruz como único fundamento de nuestra salvación?', r: 'Sí; porque el Espíritu Santo nos enseña en el evangelio y nos asegura por los sacramentos que toda nuestra salvación se apoya en el único sacrificio de Cristo.', refs: ['Ro 6:3','Gá 3:27','He 9:12'] },
      { p: '¿Cuántos sacramentos ha instituido Cristo en el Nuevo Testamento?', r: 'Dos: el santo bautismo y la Cena del Señor.', refs: ['Mt 28:19','1 Co 11:23-26'] },
      { p: '¿Cómo se te significa y sella en el bautismo que participas del único sacrificio de Cristo?', r: 'Que Cristo instituyó este lavamiento exterior con agua, y le añadió la promesa de que soy lavado con su sangre y su Espíritu de la inmundicia de mi alma, esto es, de todos mis pecados, tan ciertamente como soy lavado exteriormente con el agua.', refs: ['Mt 28:19','Mr 16:16','Hch 22:16','Ro 6:4'] },
      { p: '¿Qué es ser lavado con la sangre y el Espíritu de Cristo?', r: 'Es recibir de Dios el perdón de los pecados por gracia, por causa de la sangre de Cristo derramada por nosotros; y también ser renovados por el Espíritu Santo y santificados para ser miembros de Cristo, a fin de morir cada vez más al pecado y vivir en santidad e irreprensiblemente.', refs: ['He 12:24','1 P 1:2','1 Co 6:11','Ro 6:4','Col 2:12'] },
      { p: '¿Dónde ha prometido Cristo que seremos tan ciertamente lavados con su sangre y Espíritu como con el agua del bautismo?', r: 'En la institución del bautismo: «Id y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, del Hijo y del Espíritu Santo»; y: «El que creyere y fuere bautizado, será salvo».', refs: ['Mt 28:19','Mr 16:16'] },
      { p: '¿A quiénes se ha de administrar el bautismo?', r: 'Solo a los que realmente profesan arrepentimiento para con Dios y fe en nuestro Señor Jesucristo; porque en las Escrituras el bautismo se administra a los que creen, y no hay ni mandato ni ejemplo de bautizar a los infantes.', refs: ['Hch 2:38','Hch 8:12,36-37','Mr 16:16','Hch 18:8'] },
      { p: '¿Cómo se administra correctamente el bautismo?', r: 'Por inmersión, sumergiendo a la persona en agua en el nombre del Padre, del Hijo y del Espíritu Santo; conforme al sentido de la palabra y al ejemplo de Cristo y de los apóstoles, pues así se representa la sepultura y resurrección con él.', refs: ['Mt 3:16','Jn 3:23','Hch 8:38-39','Ro 6:4','Col 2:12'] },
      { p: '¿Es, pues, el mismo lavamiento exterior del agua el que quita los pecados?', r: 'No; porque solo la sangre de Jesucristo y el Espíritu Santo nos limpian de todo pecado.', refs: ['1 Jn 1:7','1 Co 6:11','1 P 3:21'] },
      { p: '¿Por qué, entonces, llama el Espíritu Santo al bautismo «el lavamiento de la regeneración»?', r: 'Dios habla así con gran razón: no solo para enseñarnos que, como la suciedad del cuerpo se quita con el agua, así nuestros pecados se quitan por la sangre y el Espíritu de Cristo; sino mucho más para asegurarnos, por esta prenda divina, que somos lavados de nuestros pecados espiritualmente tan cierto como lo somos con el agua corporal.', refs: ['Ap 1:5','Ap 7:14','Tit 3:5','1 Co 6:11'] },
      { p: '¿Cómo se te significa y sella en la Cena del Señor que participas del único sacrificio de Cristo y de todos sus beneficios?', r: 'Que Cristo me mandó a mí y a todos los creyentes comer de este pan partido y beber de esta copa en memoria suya, añadiendo la promesa de que su cuerpo fue ofrecido y partido por mí en la cruz, y su sangre derramada por mí, tan ciertamente como veo con mis ojos el pan partido y la copa dada.', refs: ['1 Co 11:23-25','Mt 26:26-28','Mr 14:22-24'] },
      { p: '¿Qué es comer el cuerpo crucificado y beber la sangre derramada de Cristo?', r: 'No es solo abrazar con corazón creyente toda la pasión y muerte de Cristo, y por ello alcanzar el perdón y la vida eterna; sino también, por el Espíritu Santo que mora en Cristo y en nosotros, ser cada vez más unidos a su cuerpo sagrado, de modo que, aunque él esté en el cielo y nosotros en la tierra, somos carne de su carne y hueso de sus huesos, y vivimos y somos gobernados eternamente por un mismo Espíritu.', refs: ['Jn 6:35,40,50-54','Ef 5:29-30','1 Co 6:15,17','1 Jn 4:13'] },
      { p: '¿Se convierten, pues, el pan y el vino en el verdadero cuerpo y sangre de Cristo?', r: 'No; sino que, así como el agua del bautismo no se convierte en la sangre de Cristo, sino que es solo señal y prenda de ello, así tampoco el pan de la Cena es el cuerpo mismo de Cristo, aunque, conforme a la naturaleza y el uso de los sacramentos, se le llame el cuerpo de Cristo.', refs: ['Mt 26:29','1 Co 10:16-17','1 Co 11:26-28','Éx 12:11,13'] },
      { p: '¿Qué diferencia hay entre la Cena del Señor y la misa papal?', r: 'La Cena del Señor nos atestigua que tenemos pleno perdón de todos nuestros pecados por el único sacrificio de Jesucristo, consumado una sola vez en la cruz; pero la misa enseña que los vivos y los muertos no tienen perdón por la pasión de Cristo, a menos que él sea aún cada día ofrecido por los sacerdotes; y así la misa no es sino una negación del único sacrificio de Cristo, y una idolatría abominable.', refs: ['He 10:10,12,14','He 9:25-28','Jn 19:30','Mt 26:28'] },
      { p: '¿Quiénes han de venir a la mesa del Señor?', r: 'Los que verdaderamente se duelen de sus pecados, y sin embargo confían en que les son perdonados por causa de Cristo, y en que su restante flaqueza está cubierta por su pasión y muerte; y que desean cada vez más fortalecer su fe y enmendar su vida.', refs: ['1 Co 11:28','1 Co 10:19-22','1 Co 11:26'] },
      { p: '¿Han de ser admitidos también a esta Cena los que por su confesión y su vida se muestran incrédulos e impíos?', r: 'No; porque así se profana el pacto de Dios y se provoca su ira sobre toda la congregación; por lo cual la iglesia está obligada, conforme al orden de Cristo y de sus apóstoles, a excluirlos por el poder de las llaves hasta que muestren enmienda de vida.', refs: ['1 Co 11:20,34','Is 1:11-15','1 Co 5:11-13','Mt 7:6'] },
      { p: 'Puesto que somos redimidos de nuestra miseria por gracia, sin mérito nuestro, ¿por qué hemos de hacer buenas obras?', r: 'Porque Cristo, habiéndonos redimido con su sangre, también nos renueva por su Espíritu a su imagen, para que con toda nuestra vida nos mostremos agradecidos a Dios por sus beneficios y él sea glorificado; y también para que cada uno esté seguro de su fe por sus frutos, y con nuestra vida piadosa ganemos a otros para Cristo.', refs: ['Ro 6:13','1 P 2:5,9','Mt 5:16','2 P 1:10','Mt 7:17'] },
      { p: '¿No pueden, pues, ser salvos los que, perseverando en su vida malvada e ingrata, no se convierten a Dios?', r: 'De ninguna manera; porque, como dice la Escritura, ningún impuro, idólatra, adúltero, ladrón, avaro ni borracho heredará el reino de Dios.', refs: ['1 Co 6:9-10','Ef 5:5-6','1 Jn 3:14'] },
      { p: '¿De cuántas partes consta la verdadera conversión del hombre?', r: 'De dos: la mortificación del viejo hombre y la vivificación del nuevo.', refs: ['Ro 6:4-6','Ef 4:22-24','Col 3:5-10'] },
      { p: '¿Qué es la mortificación del viejo hombre?', r: 'Es un dolor sincero por haber ofendido a Dios con nuestros pecados, y aborrecerlos y huir de ellos cada vez más.', refs: ['Ro 8:13','Jl 2:13','Ro 6:6','Sal 51:3-4,17'] },
      { p: '¿Qué es la vivificación del nuevo hombre?', r: 'Es un gozo cordial en Dios por Cristo, y un amor y deleite en vivir conforme a la voluntad de Dios en toda clase de buenas obras.', refs: ['Ro 5:1','Ro 14:17','Is 57:15','Ro 6:10-11','Gá 2:20'] },
      { p: '¿Qué son buenas obras?', r: 'Solo aquellas que proceden de una verdadera fe, son hechas conforme a la ley de Dios y para su gloria; y no las que se fundan en nuestro parecer o en mandamientos de hombres.', refs: ['Ro 14:23','1 S 15:22','Ef 2:10','Mt 15:9'] },
      { p: '¿Cuál es la ley de Dios?', r: 'Los Diez Mandamientos que Dios pronunció en el monte Sinaí: no tener otros dioses; no hacer imágenes; no tomar su nombre en vano; guardar el día de reposo; honrar padre y madre; no matar; no adulterar; no hurtar; no dar falso testimonio; no codiciar.', refs: ['Éx 20:1-17','Dt 5:6-21'] },
      { p: '¿Cómo se dividen estos mandamientos?', r: 'En dos tablas: la primera enseña, en cuatro mandamientos, cómo hemos de comportarnos para con Dios; la segunda, en seis, qué debemos a nuestro prójimo.', refs: ['Mt 22:37-40','Éx 34:28','Dt 4:13'] },
      { p: '¿Qué requiere Dios en el primer mandamiento?', r: 'Que, so pena de perder mi alma, evite y huya de toda idolatría, hechicería, superstición e invocación de los santos o de otras criaturas; y que reconozca al único y verdadero Dios, confíe solo en él, con humildad y paciencia le espere, de solo él aguarde todo bien, y le ame, tema y honre de todo corazón.', refs: ['1 Co 10:14','Mt 4:10','Jer 17:5,7','Dt 6:5'] },
      { p: '¿Qué exige Dios en el segundo mandamiento?', r: 'Que de ninguna manera representemos a Dios con imágenes, ni le rindamos culto de otro modo que el que él ha mandado en su Palabra.', refs: ['Dt 4:15-19','Is 40:18,25','Ro 1:23','Dt 12:30-32'] },
      { p: '¿Qué exige Dios en el tercer mandamiento?', r: 'Que no profanemos ni abusemos del nombre de Dios con maldición, juramento falso o innecesario, ni por el silencio seamos partícipes de tales pecados; sino que usemos su santo nombre solo con temor y reverencia, para que sea confesado, invocado y glorificado en todas nuestras palabras y obras.', refs: ['Lv 24:15-16','Mt 5:34-37','Stg 5:12','Sal 99:3','Jer 4:2'] },
      { p: '¿Qué exige Dios en el cuarto mandamiento?', r: 'Primero, que se mantenga el ministerio del evangelio, y que yo, especialmente en el día de reposo, acuda diligentemente a la iglesia para oír la Palabra, usar los sacramentos, invocar al Señor y dar ofrenda cristiana para los pobres. Segundo, que todos los días de mi vida repose de mis malas obras, deje que el Señor obre en mí por su Espíritu, y así comience ya aquí el reposo eterno.', refs: ['1 Ti 4:13','1 Co 16:1-2','Hch 20:7','Is 66:23','He 4:9-10'] },
      { p: '¿Qué exige Dios en el quinto mandamiento?', r: 'Que tribute a mi padre y a mi madre, y a todos los que tienen autoridad sobre mí, todo honor, amor y fidelidad; que me someta con la debida obediencia a sus buenas instrucciones y correcciones, y tenga también paciencia con sus faltas, pues Dios ha querido gobernarnos por su mano.', refs: ['Ef 6:1-9','Col 3:18-24','Ro 13:1-7','Pr 23:22'] },
      { p: '¿Qué exige Dios en el sexto mandamiento?', r: 'Que ni con pensamientos, ni con palabras, ni con gestos, ni mucho menos con obras, deshonre, aborrezca, hiera o mate a mi prójimo, por mí mismo o por otro; sino que deponga todo deseo de venganza, y que tampoco me dañe a mí mismo ni me exponga temerariamente al peligro.', refs: ['Mt 5:21-22','Ro 12:19','Ef 4:26','Mt 4:7','Gn 9:6'] },
      { p: '¿Qué exige Dios en el séptimo mandamiento?', r: 'Que toda impureza es maldita por Dios, y que por ello debemos aborrecerla de corazón, y vivir casta y honestamente, tanto en el matrimonio santo como fuera de él.', refs: ['Jud 22-23','1 Ts 4:3-5','He 13:4','1 Co 6:18-20'] },
      { p: '¿Qué prohíbe Dios en el octavo mandamiento?', r: 'No solo el hurto y el robo que las autoridades castigan, sino también todo engaño y ardid con que pretendamos apropiarnos de los bienes del prójimo, con violencia o con apariencia de derecho, con pesas y medidas falsas, con usura o con cualquier medio prohibido por Dios; y también toda avaricia y todo abuso o desperdicio de sus dones.', refs: ['1 Co 6:10','Lc 3:14','Pr 11:1','Ez 45:9-12','1 Co 5:10-11'] },
      { p: '¿Qué exige el noveno mandamiento?', r: 'Que no dé falso testimonio contra nadie, ni tuerza las palabras de otro, ni sea murmurador o calumniador, ni condene a nadie sin oírle o a la ligera; sino que evite toda mentira y engaño como obras propias del diablo, ame la verdad, la hable y la confiese, y cuide y promueva, en cuanto pueda, el honor y el buen nombre de mi prójimo.', refs: ['Pr 19:5,9','Sal 15:3','Ro 1:29-30','Lv 19:11-12','Ef 4:25','1 P 4:8'] },
      { p: '¿Qué exige de nosotros el décimo mandamiento?', r: 'Que ni el menor deseo o pensamiento contrario a cualquier mandamiento de Dios suba jamás a nuestro corazón; sino que, en todo tiempo, aborrezcamos de todo corazón todo pecado y nos deleitemos en toda justicia.', refs: ['Ro 7:7-8','Sal 19:12-13','Stg 1:14-15','Mt 5:28'] },
      { p: '¿Pueden los convertidos a Dios guardar perfectamente estos mandamientos?', r: 'No; pues aun los más santos, mientras viven, tienen solo un pequeño comienzo de esta obediencia; pero de tal manera que, con serio propósito, empiezan a vivir no solo según algunos, sino según todos los mandamientos de Dios.', refs: ['1 Jn 1:8-10','Ro 7:14-15','Ec 7:20','Ro 7:22','Sal 1:2'] },
      { p: 'Puesto que nadie puede guardarlos perfectamente en esta vida, ¿por qué quiere Dios que se prediquen con tal rigor?', r: 'Primero, para que toda nuestra vida conozcamos cada vez más nuestra naturaleza pecaminosa, y busquemos con más ardor el perdón y la justicia en Cristo. Segundo, para que sin cesar nos esforcemos y pidamos a Dios la gracia del Espíritu Santo, a fin de ser cada vez más renovados a su imagen, hasta alcanzar la perfección después de esta vida.', refs: ['Ro 3:20','1 Jn 1:9','Mt 5:6','1 Co 9:24-25','Fil 3:12-14'] },
      { p: '¿Por qué es necesaria para los cristianos la oración?', r: 'Porque es la parte principal de la gratitud que Dios requiere de nosotros; y porque Dios quiere dar su gracia y su Espíritu Santo solo a los que de corazón y sin cesar se los piden y le dan gracias por ellos.', refs: ['Sal 50:14-15','Mt 7:7-8','Lc 11:13','1 Ts 5:17'] },
      { p: '¿Qué se requiere en una oración que agrade a Dios y sea oída por él?', r: 'Primero, que invoquemos de corazón solo al único Dios verdadero, por todo lo que nos ha mandado pedir. Segundo, que conozcamos bien nuestra necesidad y miseria, para humillarnos delante de su majestad. Tercero, que tengamos el firme fundamento de que, a pesar de nuestra indignidad, Dios ciertamente oirá nuestra oración por causa de Cristo, como lo ha prometido.', refs: ['Sal 145:18','Jn 4:24','2 Cr 20:12','Sal 143:1-2','Jn 16:23','Dn 9:17-18'] },
      { p: '¿Qué nos ha mandado Dios que le pidamos?', r: 'Todo lo necesario para el alma y el cuerpo, que Cristo nuestro Señor comprendió en la oración que él mismo nos enseñó.', refs: ['Stg 1:17','Mt 6:33','Mt 6:9-13'] },
      { p: '¿Cuál es esa oración?', r: 'Padre nuestro que estás en los cielos: santificado sea tu nombre. Venga tu reino. Hágase tu voluntad, como en el cielo, así también en la tierra. El pan nuestro de cada día, dánoslo hoy. Y perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores. Y no nos metas en tentación, mas líbranos del mal; porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén.', refs: ['Mt 6:9-13','Lc 11:2-4'] },
      { p: '¿Por qué nos ha mandado Cristo dirigirnos a Dios así: «Padre nuestro»?', r: 'Para que desde el comienzo de nuestra oración despierte en nosotros aquella reverencia y confianza filial hacia Dios que ha de ser el fundamento de nuestra oración: que Dios es nuestro Padre por Cristo, y no nos negará mucho menos lo que con fe le pedimos, que lo que nuestros padres terrenos nos niegan de las cosas terrenas.', refs: ['Mt 7:9-11','Lc 11:11-13','Ro 8:15','Is 63:16'] },
      { p: '¿Por qué se añade: «que estás en los cielos»?', r: 'Para que no pensemos terrenalmente de la majestad celestial de Dios, y esperemos de su omnipotencia todo lo necesario para el cuerpo y el alma.', refs: ['Jer 23:23-24','Hch 17:24-25,27','Ro 10:12'] },
      { p: '¿Cuál es la primera petición?', r: '«Santificado sea tu nombre»; esto es: danos conocerte rectamente, y santificar, ensalzar y alabar tu omnipotencia, sabiduría, bondad, justicia, misericordia y verdad; y ordena toda nuestra vida —pensamientos, palabras y obras— de modo que tu nombre no sea blasfemado por nuestra causa, sino honrado y alabado.', refs: ['Jn 17:3','Jer 9:23-24','Sal 71:8','Mt 5:16'] },
      { p: '¿Cuál es la segunda petición?', r: '«Venga tu reino»; esto es: gobiérnanos por tu Palabra y tu Espíritu, de modo que cada vez más nos sometamos a ti; conserva y aumenta tu iglesia; destruye las obras del diablo y todo poder que se levante contra ti y contra tu santa Palabra; hasta que venga la plenitud de tu reino, en la que serás todo en todos.', refs: ['Sal 143:10','Mt 6:33','Sal 51:18','Ro 16:20','1 Co 15:28','Ap 22:20'] },
      { p: '¿Cuál es la tercera petición?', r: '«Hágase tu voluntad, como en el cielo, así también en la tierra»; esto es: haz que nosotros y todos los hombres renunciemos a nuestra propia voluntad, y obedezcamos sin réplica a tu voluntad, la única buena; para que cada uno cumpla el oficio y la vocación que le has dado tan pronta y fielmente como los ángeles en el cielo.', refs: ['Mt 16:24','Tit 2:11-12','Lc 22:42','Ef 6:6','Sal 103:20-21'] },
      { p: '¿Cuál es la cuarta petición?', r: '«El pan nuestro de cada día, dánoslo hoy»; esto es: provee para todas nuestras necesidades corporales, para que reconozcamos que tú eres la única fuente de todo bien, y que sin tu bendición ni nuestro trabajo ni tus dones nos aprovechan; y que así apartemos nuestra confianza de toda criatura y la pongamos solo en ti.', refs: ['Sal 104:27-30','Sal 145:15-16','Mt 6:25-26','Sal 55:22','Jer 17:5,7'] },
      { p: '¿Cuál es la quinta petición?', r: '«Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores»; esto es: no nos imputes, por causa de la sangre de Cristo, ninguno de nuestros pecados, ni la corrupción que aún mora en nosotros; así como nosotros sentimos en nuestro corazón este testimonio de tu gracia: el firme propósito de perdonar de corazón a nuestro prójimo.', refs: ['Sal 51:1-7','1 Jn 2:1-2','Mt 6:14-15','Mt 18:21-35'] },
      { p: '¿Cuál es la sexta petición?', r: '«Y no nos metas en tentación, mas líbranos del mal»; esto es: puesto que por nosotros mismos somos tan débiles que no podemos mantenernos ni un momento, y nuestros enemigos jurados —el diablo, el mundo y nuestra propia carne— no cesan de combatirnos, sostennos y fortalécenos con el poder de tu Espíritu Santo, para que no seamos vencidos en esta guerra espiritual, sino que resistamos firmemente hasta alcanzar la victoria completa.', refs: ['Jn 15:5','Mt 26:41','1 P 5:8','Ef 6:12-13','1 Ts 3:13'] },
      { p: '¿Cómo concluyes esta oración?', r: '«Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos»; esto es: todo esto te pedimos porque tú, como nuestro Rey todopoderoso, quieres y puedes darnos todo bien, para que por ello no nosotros, sino tu santo nombre, sea glorificado eternamente.', refs: ['Ro 11:36','2 P 2:9','Jn 14:13','Sal 115:1'] },
      { p: '¿Qué significa la palabra «Amén»?', r: '«Amén» significa: así será verdadera y ciertamente; porque mi oración es mucho más ciertamente oída por Dios de lo que yo siento en mi corazón que deseo tales cosas de él.', refs: ['2 Co 1:20','2 Ti 2:13','Is 65:24'] }
    ]
  },

  wmenor: {
    titulo: 'Catecismo Menor de Westminster',
    sub: 'Westminster · Menor',
    nota: 'El Catecismo Menor (Shorter Catechism) de la Asamblea de Westminster (1647), compuesto para instruir a los sencillos y a los niños en la fe reformada. Presbiteriano; su enseñanza sobre el bautismo incluye a los hijos de los creyentes (paidobautismo). Fue la base sobre la que Keach compuso el Catecismo Bautista de 1693.',
    fuente: 'Catecismo Menor de Westminster (1647) · texto de dominio público. Toca una referencia para leerla en la Biblia.',
    preguntas: [
      { p: '¿Cuál es el fin principal del hombre?', r: 'El fin principal del hombre es glorificar a Dios y gozar de él para siempre.', refs: ['1 Co 10:31','Ro 11:36','Sal 73:25-26'] },
      { p: '¿Qué regla ha dado Dios para dirigirnos en cómo glorificarle y gozar de él?', r: 'La Palabra de Dios, contenida en las Escrituras del Antiguo y Nuevo Testamento, es la única regla que Dios ha dado para dirigirnos en cómo glorificarle y gozar de él.', refs: ['2 Ti 3:16','Ef 2:20','1 Jn 1:3-4'] },
      { p: '¿Qué enseñan principalmente las Escrituras?', r: 'Las Escrituras enseñan principalmente lo que el hombre ha de creer acerca de Dios, y qué deber Dios requiere del hombre.', refs: ['2 Ti 1:13','Ec 12:13'] },
      { p: '¿Qué es Dios?', r: 'Dios es Espíritu, infinito, eterno e inmutable en su ser, sabiduría, poder, santidad, justicia, bondad y verdad.', refs: ['Jn 4:24','Sal 90:2','Stg 1:17','Éx 3:14','Sal 147:5','Ap 4:8','Éx 34:6-7'] },
      { p: '¿Hay más de un Dios?', r: 'No hay más que uno solo, el Dios vivo y verdadero.', refs: ['Dt 6:4','Jer 10:10'] },
      { p: '¿Cuántas personas hay en la Deidad?', r: 'Hay tres personas en la Deidad: el Padre, el Hijo y el Espíritu Santo; y estas tres son un solo Dios, el mismo en sustancia, iguales en poder y gloria.', refs: ['Mt 28:19','1 Jn 5:7','2 Co 13:14'] },
      { p: '¿Qué son los decretos de Dios?', r: 'Los decretos de Dios son su propósito eterno, según el consejo de su voluntad, por el cual, para su propia gloria, ha preordenado todo cuanto sucede.', refs: ['Ef 1:11','Ro 9:22-23','Ro 11:33'] },
      { p: '¿Cómo ejecuta Dios sus decretos?', r: 'Dios ejecuta sus decretos en las obras de la creación y de la providencia.', refs: ['Ap 4:11','Dn 4:35'] },
      { p: '¿Qué es la obra de la creación?', r: 'La obra de la creación es aquella por la cual Dios hizo todas las cosas de la nada, por la palabra de su poder, en el espacio de seis días, y todo muy bueno.', refs: ['Gn 1:1','He 11:3','Éx 20:11','Gn 1:31'] },
      { p: '¿Cómo creó Dios al hombre?', r: 'Dios creó al hombre, varón y mujer, a su propia imagen, en conocimiento, justicia y santidad, con dominio sobre las criaturas.', refs: ['Gn 1:26-28','Col 3:10','Ef 4:24'] },
      { p: '¿Cuáles son las obras de providencia de Dios?', r: 'Las obras de providencia de Dios son su santísima, sapientísima y poderosísima preservación y gobierno de todas sus criaturas y de todas sus acciones.', refs: ['Sal 145:17','Sal 103:19','Mt 10:29-31','He 1:3'] },
      { p: '¿Qué acto especial de providencia ejerció Dios hacia el hombre en el estado en que fue creado?', r: 'Cuando Dios creó al hombre, hizo con él un pacto de vida bajo la condición de una obediencia perfecta, prohibiéndole comer del árbol del conocimiento del bien y del mal, bajo pena de muerte.', refs: ['Gá 3:12','Gn 2:17'] },
      { p: '¿Permanecieron nuestros primeros padres en el estado en que fueron creados?', r: 'Nuestros primeros padres, dejados a la libertad de su propia voluntad, cayeron del estado en que fueron creados, pecando contra Dios.', refs: ['Gn 3:6-8,13','Ec 7:29'] },
      { p: '¿Qué es el pecado?', r: 'El pecado es toda falta de conformidad con la ley de Dios, o toda transgresión de ella.', refs: ['1 Jn 3:4'] },
      { p: '¿Cuál fue el pecado por el que nuestros primeros padres cayeron del estado en que fueron creados?', r: 'El pecado por el que nuestros primeros padres cayeron del estado en que fueron creados fue comer del fruto prohibido.', refs: ['Gn 3:6,12'] },
      { p: '¿Cayó toda la humanidad en la primera transgresión de Adán?', r: 'Habiéndose hecho el pacto con Adán, no solo para sí mismo sino también para su posteridad, toda la humanidad que desciende de él por generación ordinaria pecó en él y cayó con él en su primera transgresión.', refs: ['Gn 2:16-17','Ro 5:12','1 Co 15:21-22'] },
      { p: '¿A qué estado llevó la caída a la humanidad?', r: 'La caída llevó a la humanidad a un estado de pecado y de miseria.', refs: ['Ro 5:12','Ro 3:23'] },
      { p: '¿En qué consiste la pecaminosidad de aquel estado en que cayó el hombre?', r: 'La pecaminosidad de aquel estado consiste en la culpa del primer pecado de Adán, la falta de justicia original y la corrupción de toda su naturaleza, que comúnmente se llama pecado original, junto con todas las transgresiones que de él proceden.', refs: ['Ro 5:12,19','Ef 2:1-3','Stg 1:14-15','Mt 15:19'] },
      { p: '¿Cuál es la miseria de aquel estado en que cayó el hombre?', r: 'Toda la humanidad, por su caída, perdió la comunión con Dios, quedó bajo su ira y maldición, y así hecha sujeta a todas las miserias de esta vida, a la muerte misma, y a las penas del infierno para siempre.', refs: ['Gn 3:8,24','Ef 2:3','Gá 3:10','Lm 3:39','Ro 6:23','Mt 25:41'] },
      { p: '¿Dejó Dios que toda la humanidad pereciera en el estado de pecado y miseria?', r: 'Dios, por su mero beneplácito, desde toda la eternidad, habiendo escogido a algunos para vida eterna, entró en un pacto de gracia para librarlos del estado de pecado y miseria, y traerlos a un estado de salvación por un Redentor.', refs: ['Ef 1:3-4','2 Ts 2:13-14','Ro 5:21'] },
      { p: '¿Quién es el Redentor de los elegidos de Dios?', r: 'El único Redentor de los elegidos de Dios es el Señor Jesucristo, quien, siendo el eterno Hijo de Dios, se hizo hombre, y así fue y sigue siendo Dios y hombre, en dos naturalezas distintas y una sola persona, para siempre.', refs: ['1 Ti 2:5-6','Jn 1:14','Gá 4:4','Col 2:9','He 7:24-25'] },
      { p: '¿Cómo llegó Cristo, siendo el Hijo de Dios, a ser hombre?', r: 'Cristo, el Hijo de Dios, se hizo hombre tomando para sí un cuerpo verdadero y un alma racional, siendo concebido por el poder del Espíritu Santo en el vientre de la virgen María, y nacido de ella, mas sin pecado.', refs: ['Jn 1:14','He 2:14,16-17','Lc 1:27,31,35','He 4:15'] },
      { p: '¿Qué oficios cumple Cristo como nuestro Redentor?', r: 'Cristo, como nuestro Redentor, cumple los oficios de profeta, de sacerdote y de rey, tanto en su estado de humillación como en el de exaltación.', refs: ['Hch 3:22','He 5:5-6','Sal 2:6'] },
      { p: '¿Cómo cumple Cristo el oficio de profeta?', r: 'Cristo cumple el oficio de profeta al revelarnos, por su Palabra y su Espíritu, la voluntad de Dios para nuestra salvación.', refs: ['Jn 1:18','1 P 1:10-12','Jn 15:15','Jn 20:31'] },
      { p: '¿Cómo cumple Cristo el oficio de sacerdote?', r: 'Cristo cumple el oficio de sacerdote al ofrecerse a sí mismo una sola vez en sacrificio para satisfacer la justicia divina y reconciliarnos con Dios, y al interceder continuamente por nosotros.', refs: ['He 9:14,28','He 2:17','He 7:24-25'] },
      { p: '¿Cómo cumple Cristo el oficio de rey?', r: 'Cristo cumple el oficio de rey al sujetarnos a sí mismo, gobernarnos y defendernos, y refrenar y vencer a todos sus enemigos y los nuestros.', refs: ['Sal 110:3','1 Co 15:25','Col 1:13'] },
      { p: '¿En qué consistió la humillación de Cristo?', r: 'La humillación de Cristo consistió en haber nacido, y eso en baja condición; en ser hecho bajo la ley; en padecer las miserias de esta vida, la ira de Dios y la muerte maldita de la cruz; en ser sepultado y permanecer bajo el poder de la muerte por un tiempo.', refs: ['Lc 2:7','Gá 4:4','Is 53:2-3','Lc 22:44','Fil 2:8','1 Co 15:3-4'] },
      { p: '¿En qué consiste la exaltación de Cristo?', r: 'La exaltación de Cristo consiste en su resurrección de entre los muertos al tercer día, su ascensión al cielo, su sesión a la diestra de Dios Padre, y su venida para juzgar al mundo en el día postrero.', refs: ['1 Co 15:4','Mr 16:19','Ef 1:20','Hch 1:11','Hch 17:31'] },
      { p: '¿Cómo somos hechos partícipes de la redención comprada por Cristo?', r: 'Somos hechos partícipes de la redención comprada por Cristo por la aplicación eficaz de ella a nosotros, por su Santo Espíritu.', refs: ['Jn 1:12','Tit 3:5-6'] },
      { p: '¿Cómo aplica el Espíritu la redención comprada por Cristo?', r: 'El Espíritu aplica la redención comprada por Cristo obrando en nosotros la fe, y uniéndonos así a Cristo en nuestro llamamiento eficaz.', refs: ['Ef 2:8','Ef 3:17','1 Co 1:9'] },
      { p: '¿Qué es el llamamiento eficaz?', r: 'El llamamiento eficaz es la obra del Espíritu de Dios, por la cual, convenciéndonos de nuestro pecado y miseria, iluminando nuestras mentes en el conocimiento de Cristo, y renovando nuestra voluntad, nos persuade y capacita para abrazar a Jesucristo, ofrecido gratuitamente a nosotros en el evangelio.', refs: ['2 Ti 1:9','Hch 26:18','Ez 36:26-27','Jn 6:44-45','Fil 2:13'] },
      { p: '¿De qué beneficios participan en esta vida los que son llamados eficazmente?', r: 'Los que son llamados eficazmente participan en esta vida de la justificación, la adopción, la santificación, y los diversos beneficios que en esta vida las acompañan o de ellas proceden.', refs: ['Ro 8:30','Ef 1:5','1 Co 6:11','Ro 5:1-2,5'] },
      { p: '¿Qué es la justificación?', r: 'La justificación es un acto de la gracia gratuita de Dios, por el cual perdona todos nuestros pecados y nos acepta como justos ante sus ojos, solo por causa de la justicia de Cristo imputada a nosotros, y recibida solo por la fe.', refs: ['Ro 3:24','Ef 1:7','2 Co 5:19,21','Ro 5:19','Gá 2:16','Fil 3:9'] },
      { p: '¿Qué es la adopción?', r: 'La adopción es un acto de la gracia gratuita de Dios, por el cual somos recibidos en el número de los hijos de Dios y tenemos derecho a todos sus privilegios.', refs: ['1 Jn 3:1','Jn 1:12','Ro 8:17'] },
      { p: '¿Qué es la santificación?', r: 'La santificación es la obra de la gracia gratuita de Dios, por la cual somos renovados en todo nuestro ser a imagen de Dios, y capacitados cada vez más para morir al pecado y vivir para la justicia.', refs: ['2 Ts 2:13','Ef 4:23-24','Ro 6:4,6'] },
      { p: '¿Qué beneficios acompañan o proceden en esta vida de la justificación, la adopción y la santificación?', r: 'Los beneficios que en esta vida acompañan o proceden de la justificación, la adopción y la santificación son: la seguridad del amor de Dios, la paz de conciencia, el gozo en el Espíritu Santo, el crecimiento en gracia, y la perseverancia en ella hasta el fin.', refs: ['Ro 5:1-2,5','Ro 14:17','Pr 4:18','1 Jn 5:13','1 P 1:5'] },
      { p: '¿Qué beneficios reciben los creyentes de Cristo en la muerte?', r: 'Las almas de los creyentes son, en su muerte, hechas perfectas en santidad, y pasan inmediatamente a la gloria; y sus cuerpos, unidos todavía a Cristo, descansan en sus sepulcros hasta la resurrección.', refs: ['He 12:23','Fil 1:23','2 Co 5:8','1 Ts 4:14','Is 57:2'] },
      { p: '¿Qué beneficios reciben los creyentes de Cristo en la resurrección?', r: 'En la resurrección, los creyentes, siendo resucitados en gloria, serán reconocidos y absueltos abiertamente en el día del juicio, y hechos perfectamente bienaventurados, en el pleno gozo de Dios, por toda la eternidad.', refs: ['1 Co 15:43','Mt 25:23','1 Jn 3:2','1 Ts 4:17'] },
      { p: '¿Cuál es el deber que Dios requiere del hombre?', r: 'El deber que Dios requiere del hombre es la obediencia a su voluntad revelada.', refs: ['Miq 6:8','1 S 15:22'] },
      { p: '¿Qué reveló Dios primeramente al hombre como regla de su obediencia?', r: 'La regla que Dios reveló primeramente al hombre para su obediencia fue la ley moral.', refs: ['Ro 2:14-15','Dt 10:4'] },
      { p: '¿Dónde está resumida la ley moral?', r: 'La ley moral está resumida en los Diez Mandamientos.', refs: ['Dt 10:4','Mt 19:17'] },
      { p: '¿Cuál es el resumen de los Diez Mandamientos?', r: 'El resumen de los Diez Mandamientos es amar al Señor nuestro Dios con todo nuestro corazón, con toda nuestra alma, con todas nuestras fuerzas y con toda nuestra mente; y a nuestro prójimo como a nosotros mismos.', refs: ['Mt 22:37-40'] },
      { p: '¿Cuál es el prefacio a los Diez Mandamientos?', r: 'El prefacio a los Diez Mandamientos es: «Yo soy Jehová tu Dios, que te saqué de la tierra de Egipto, de casa de servidumbre».', refs: ['Éx 20:2'] },
      { p: '¿Qué nos enseña el prefacio a los Diez Mandamientos?', r: 'El prefacio nos enseña que, por cuanto Dios es el Señor, y nuestro Dios y Redentor, estamos obligados a guardar todos sus mandamientos.', refs: ['Lc 1:74-75','1 P 1:15-19'] },
      { p: '¿Cuál es el primer mandamiento?', r: 'El primer mandamiento es: «No tendrás dioses ajenos delante de mí».', refs: ['Éx 20:3'] },
      { p: '¿Qué se requiere en el primer mandamiento?', r: 'El primer mandamiento requiere que conozcamos y reconozcamos a Dios como el único Dios verdadero, y Dios nuestro, y que le adoremos y glorifiquemos en consecuencia.', refs: ['1 Cr 28:9','Dt 26:17','Mt 4:10'] },
      { p: '¿Qué se prohíbe en el primer mandamiento?', r: 'El primer mandamiento prohíbe negar o no adorar y glorificar al Dios verdadero como Dios nuestro, y dar aquella adoración y gloria a cualquier otro que solo a él pertenece.', refs: ['Sal 14:1','Ro 1:20-21,25'] },
      { p: '¿Qué se nos enseña especialmente con las palabras «delante de mí» del primer mandamiento?', r: 'Las palabras «delante de mí» nos enseñan que Dios, que todo lo ve, observa y le desagrada el pecado de tener cualquier otro dios.', refs: ['Sal 44:20-21','Ez 8:12'] },
      { p: '¿Cuál es el segundo mandamiento?', r: '«No te harás imagen, ni ninguna semejanza de lo que esté arriba en el cielo, ni abajo en la tierra... No te inclinarás a ellas, ni las honrarás...».', refs: ['Éx 20:4-6'] },
      { p: '¿Qué se requiere en el segundo mandamiento?', r: 'El segundo mandamiento requiere que recibamos, observemos y guardemos puros y enteros todo el culto y las ordenanzas religiosas que Dios ha establecido en su Palabra.', refs: ['Dt 32:46','Mt 28:20','Dt 12:32'] },
      { p: '¿Qué se prohíbe en el segundo mandamiento?', r: 'El segundo mandamiento prohíbe adorar a Dios por medio de imágenes, o de cualquier otra manera no señalada en su Palabra.', refs: ['Dt 4:15-19','Éx 32:5,8','Col 2:18'] },
      { p: '¿Cuáles son las razones añadidas al segundo mandamiento?', r: 'Las razones añadidas al segundo mandamiento son: el señorío de Dios sobre nosotros, su propiedad sobre nosotros, y el celo que tiene por su propio culto.', refs: ['Sal 95:2-3,6','Éx 34:14'] },
      { p: '¿Cuál es el tercer mandamiento?', r: '«No tomarás el nombre de Jehová tu Dios en vano...».', refs: ['Éx 20:7'] },
      { p: '¿Qué se requiere en el tercer mandamiento?', r: 'El tercer mandamiento requiere el uso santo y reverente de los nombres, títulos, atributos, ordenanzas, Palabra y obras de Dios.', refs: ['Sal 29:2','Ap 15:3-4','Ec 5:1'] },
      { p: '¿Qué se prohíbe en el tercer mandamiento?', r: 'El tercer mandamiento prohíbe todo abuso o profanación de aquello por lo cual Dios se da a conocer.', refs: ['Mal 1:6-7','Lv 19:12'] },
      { p: '¿Cuál es la razón añadida al tercer mandamiento?', r: 'La razón añadida al tercer mandamiento es que, aunque los que quebrantan este mandamiento puedan escapar del castigo de los hombres, el Señor nuestro Dios no permitirá que escapen de su justo juicio.', refs: ['Éx 20:7','Dt 28:58-59','1 S 3:13'] },
      { p: '¿Cuál es el cuarto mandamiento?', r: '«Acuérdate del día de reposo para santificarlo...».', refs: ['Éx 20:8-11'] },
      { p: '¿Qué se requiere en el cuarto mandamiento?', r: 'El cuarto mandamiento requiere que se guarde santo para Dios el tiempo que él ha señalado en su Palabra, particularmente un día entero de cada siete, como día de reposo santo para él.', refs: ['Éx 20:8,10','Lv 19:30'] },
      { p: '¿Cuál de los siete días ha señalado Dios como día de reposo semanal?', r: 'Desde el principio del mundo hasta la resurrección de Cristo, Dios señaló el séptimo día de la semana como día de reposo; y el primer día de la semana desde entonces, para continuar hasta el fin del mundo, que es el día de reposo cristiano.', refs: ['Gn 2:2-3','Hch 20:7','1 Co 16:1-2','Ap 1:10'] },
      { p: '¿Cómo se ha de santificar el día de reposo?', r: 'El día de reposo se santifica con un santo descanso todo el día, aun de aquellas ocupaciones y recreaciones mundanas que en otros días son lícitas, empleando todo el tiempo en los ejercicios públicos y privados de la adoración de Dios, salvo lo necesario y lo misericordioso.', refs: ['Éx 20:8,10','Is 58:13-14','Mt 12:11-12'] },
      { p: '¿Qué se prohíbe en el cuarto mandamiento?', r: 'El cuarto mandamiento prohíbe la omisión o el cumplimiento descuidado de los deberes exigidos, y la profanación del día con ociosidad, o con hacer lo que en sí es pecaminoso, o con pensamientos, palabras u obras acerca de nuestras ocupaciones o recreaciones mundanas.', refs: ['Ez 22:26','Am 8:5','Neh 13:15-22'] },
      { p: '¿Cuáles son las razones añadidas al cuarto mandamiento?', r: 'Las razones son: que Dios nos concede seis días de la semana para nuestras propias ocupaciones, su reivindicación de la propiedad del día séptimo, su propio ejemplo, y su bendición sobre el día de reposo.', refs: ['Éx 20:9,11','Gn 2:3'] },
      { p: '¿Cuál es el quinto mandamiento?', r: '«Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da».', refs: ['Éx 20:12'] },
      { p: '¿Qué se requiere en el quinto mandamiento?', r: 'El quinto mandamiento requiere que conservemos el honor y cumplamos los deberes que corresponden a cada uno en sus diversas posiciones y relaciones, como superiores, inferiores o iguales.', refs: ['Ef 5:21-22','Ef 6:1-9','Ro 13:1,7'] },
      { p: '¿Qué se prohíbe en el quinto mandamiento?', r: 'El quinto mandamiento prohíbe descuidar o hacer cualquier cosa contra el honor y el deber que pertenecen a cada uno en sus diversas posiciones y relaciones.', refs: ['Mt 15:4-6','Ro 13:8'] },
      { p: '¿Cuál es la razón añadida al quinto mandamiento?', r: 'La razón añadida al quinto mandamiento es una promesa de larga vida y prosperidad (en cuanto sirva para la gloria de Dios y el bien propio) a todos los que lo guarden.', refs: ['Éx 20:12','Ef 6:2-3'] },
      { p: '¿Cuál es el sexto mandamiento?', r: '«No matarás».', refs: ['Éx 20:13'] },
      { p: '¿Qué se requiere en el sexto mandamiento?', r: 'El sexto mandamiento requiere todo esfuerzo lícito para conservar nuestra propia vida y la de los demás.', refs: ['Ef 5:28-29','1 R 18:4'] },
      { p: '¿Qué se prohíbe en el sexto mandamiento?', r: 'El sexto mandamiento prohíbe quitar injustamente nuestra propia vida o la del prójimo, y todo lo que a ello tienda.', refs: ['Hch 16:28','Gn 9:6','Mt 5:21-22'] },
      { p: '¿Cuál es el séptimo mandamiento?', r: '«No cometerás adulterio».', refs: ['Éx 20:14'] },
      { p: '¿Qué se requiere en el séptimo mandamiento?', r: 'El séptimo mandamiento requiere la conservación de nuestra propia castidad y la del prójimo, en corazón, palabra y conducta.', refs: ['1 Co 7:2-3,5','1 Ts 4:3-5'] },
      { p: '¿Qué se prohíbe en el séptimo mandamiento?', r: 'El séptimo mandamiento prohíbe todo pensamiento, palabra y acción impuros.', refs: ['Mt 5:28','Ef 5:3-4'] },
      { p: '¿Cuál es el octavo mandamiento?', r: '«No hurtarás».', refs: ['Éx 20:15'] },
      { p: '¿Qué se requiere en el octavo mandamiento?', r: 'El octavo mandamiento requiere procurar y promover lícitamente la riqueza y el bienestar exterior nuestro y del prójimo.', refs: ['Gn 30:30','1 Ti 5:8','Lv 25:35'] },
      { p: '¿Qué se prohíbe en el octavo mandamiento?', r: 'El octavo mandamiento prohíbe todo lo que injustamente impida o menoscabe la riqueza o el bienestar exterior nuestro o del prójimo.', refs: ['Pr 21:6','1 Ts 4:6','Ef 4:28'] },
      { p: '¿Cuál es el noveno mandamiento?', r: '«No hablarás contra tu prójimo falso testimonio».', refs: ['Éx 20:16'] },
      { p: '¿Qué se requiere en el noveno mandamiento?', r: 'El noveno mandamiento requiere mantener y promover la verdad entre los hombres, y el buen nombre nuestro y del prójimo, especialmente al dar testimonio.', refs: ['Zac 8:16','3 Jn 12','Pr 14:5,25'] },
      { p: '¿Qué se prohíbe en el noveno mandamiento?', r: 'El noveno mandamiento prohíbe todo lo que perjudique la verdad, o el buen nombre nuestro o del prójimo.', refs: ['1 S 17:28','Lv 19:16','Sal 15:3'] },
      { p: '¿Cuál es el décimo mandamiento?', r: '«No codiciarás la casa de tu prójimo, ni su mujer, ni su siervo... ni cosa alguna de tu prójimo».', refs: ['Éx 20:17'] },
      { p: '¿Qué se requiere en el décimo mandamiento?', r: 'El décimo mandamiento requiere plena satisfacción con nuestra propia condición, y una disposición recta y caritativa hacia el prójimo y todo lo que es suyo.', refs: ['He 13:5','1 Ti 6:6','Ro 12:15'] },
      { p: '¿Qué se prohíbe en el décimo mandamiento?', r: 'El décimo mandamiento prohíbe todo descontento con nuestra propia condición, la envidia o el pesar por el bien del prójimo, y todo afecto o deseo desordenado hacia lo que es suyo.', refs: ['1 Co 10:10','Stg 3:14-16','Gá 5:26','Col 3:5'] },
      { p: '¿Puede algún hombre guardar perfectamente los mandamientos de Dios?', r: 'Ningún mero hombre, desde la caída, es capaz en esta vida de guardar perfectamente los mandamientos de Dios, sino que los quebranta cada día en pensamiento, palabra y obra.', refs: ['Ec 7:20','1 Jn 1:8,10','Gá 5:17'] },
      { p: '¿Son todas las transgresiones de la ley igualmente odiosas?', r: 'Algunos pecados en sí mismos, y por razón de diversas agravantes, son más odiosos a los ojos de Dios que otros.', refs: ['Ez 8:6,13,15','1 Jn 5:16','Sal 78:17,32,56'] },
      { p: '¿Qué merece todo pecado?', r: 'Todo pecado merece la ira y la maldición de Dios, tanto en esta vida como en la venidera.', refs: ['Ef 5:6','Gá 3:10','Lm 3:39','Mt 25:41'] },
      { p: '¿Qué requiere Dios de nosotros para que escapemos de su ira y maldición debidas por el pecado?', r: 'Para escapar de la ira y maldición de Dios debidas por el pecado, Dios requiere de nosotros fe en Jesucristo y arrepentimiento para vida, junto con el uso diligente de todos los medios externos por los cuales Cristo nos comunica los beneficios de la redención.', refs: ['Hch 20:21','Hch 16:30-31','Pr 2:1-5'] },
      { p: '¿Qué es la fe en Jesucristo?', r: 'La fe en Jesucristo es una gracia salvadora por la cual recibimos a Cristo y descansamos solo en él para la salvación, tal como nos es ofrecido en el evangelio.', refs: ['He 10:39','Jn 1:12','Fil 3:9','Gá 2:16'] },
      { p: '¿Qué es el arrepentimiento para vida?', r: 'El arrepentimiento para vida es una gracia salvadora por la cual el pecador, con verdadero sentido de su pecado y con la aprehensión de la misericordia de Dios en Cristo, se vuelve de todo pecado a Dios con dolor y aborrecimiento, con el firme propósito y empeño de una nueva obediencia.', refs: ['Hch 11:18','Jl 2:12','2 Co 7:10-11','Ez 36:31'] },
      { p: '¿Cuáles son los medios externos y ordinarios por los cuales Cristo nos comunica los beneficios de la redención?', r: 'Los medios externos y ordinarios por los cuales Cristo nos comunica los beneficios de la redención son sus ordenanzas, especialmente la Palabra, los sacramentos y la oración; todos los cuales son hechos eficaces para los elegidos para su salvación.', refs: ['Mt 28:19-20','Hch 2:41-42'] },
      { p: '¿Cómo es hecha eficaz la Palabra para la salvación?', r: 'El Espíritu de Dios hace de la lectura, y especialmente de la predicación de la Palabra, un medio eficaz para convencer y convertir a los pecadores, y para edificarlos en santidad y consuelo, por la fe, para salvación.', refs: ['Neh 8:8','1 Co 14:24-25','Hch 26:18','Sal 19:7','Ro 1:16'] },
      { p: '¿Cómo se ha de leer y oír la Palabra para que sea eficaz para la salvación?', r: 'Para que la Palabra sea eficaz para la salvación, debemos atender a ella con diligencia, preparación y oración; recibirla con fe y amor, atesorarla en nuestro corazón y practicarla en nuestra vida.', refs: ['Pr 8:34','1 P 2:1-2','Sal 119:11','He 4:2','Stg 1:25'] },
      { p: '¿Cómo llegan a ser los sacramentos medios eficaces de salvación?', r: 'Los sacramentos llegan a ser medios eficaces de salvación, no por virtud alguna en ellos ni en quien los administra, sino solo por la bendición de Cristo y la obra de su Espíritu en los que por fe los reciben.', refs: ['1 P 3:21','1 Co 3:6-7','1 Co 12:13'] },
      { p: '¿Qué es un sacramento?', r: 'Un sacramento es una ordenanza santa instituida por Cristo, en la cual, por signos sensibles, Cristo y los beneficios del nuevo pacto son representados, sellados y aplicados a los creyentes.', refs: ['Gn 17:7,10','Éx 12:11','1 Co 11:23,26'] },
      { p: '¿Cuáles son los sacramentos del Nuevo Testamento?', r: 'Los sacramentos del Nuevo Testamento son el Bautismo y la Cena del Señor.', refs: ['Mt 28:19','1 Co 11:23-26'] },
      { p: '¿Qué es el bautismo?', r: 'El bautismo es un sacramento en el cual el lavamiento con agua en el nombre del Padre, del Hijo y del Espíritu Santo significa y sella nuestro injerto en Cristo, la participación de los beneficios del pacto de gracia, y nuestro compromiso de ser del Señor.', refs: ['Mt 28:19','Ro 6:4','Gá 3:27','Tit 3:5'] },
      { p: '¿A quiénes se ha de administrar el bautismo?', r: 'El bautismo no se ha de administrar a ninguno que esté fuera de la iglesia visible hasta que profese su fe en Cristo y su obediencia a él; pero los infantes de los que son miembros de la iglesia visible han de ser bautizados. (Nota: este es el punto paidobautista propio de Westminster; la 1689 y los catecismos bautistas de este mismo apartado lo limitan a los que profesan la fe.)', refs: ['Hch 8:36-37','Hch 2:38-39','Gn 17:7,10','Col 2:11-12','1 Co 7:14'] },
      { p: '¿Qué es la Cena del Señor?', r: 'La Cena del Señor es un sacramento en el cual, al dar y recibir pan y vino conforme a la designación de Cristo, se anuncia su muerte; y los que reciben dignamente participan, no de manera carnal ni corporal, sino por la fe, de su cuerpo y su sangre, con todos sus beneficios, para su alimento espiritual y crecimiento en gracia.', refs: ['1 Co 11:23-26','1 Co 10:16'] },
      { p: '¿Qué se requiere para recibir dignamente la Cena del Señor?', r: 'Se requiere de los que reciben la Cena del Señor que se examinen sobre su conocimiento para discernir el cuerpo del Señor, su fe para alimentarse de él, su arrepentimiento, amor y nueva obediencia; no sea que, viniendo indignamente, coman y beban juicio para sí.', refs: ['1 Co 11:28-29','2 Co 13:5','1 Co 5:8'] },
      { p: '¿Qué es la oración?', r: 'La oración es un ofrecimiento de nuestros deseos a Dios, por cosas conformes a su voluntad, en el nombre de Cristo, con confesión de nuestros pecados y agradecido reconocimiento de sus misericordias.', refs: ['Sal 62:8','1 Jn 5:14','Jn 16:23','Sal 32:5-6','Fil 4:6'] },
      { p: '¿Qué regla nos ha dado Dios para dirigirnos en la oración?', r: 'Toda la Palabra de Dios es útil para dirigirnos en la oración; pero la regla especial de dirección es aquella oración que Cristo enseñó a sus discípulos, comúnmente llamada el Padrenuestro.', refs: ['2 Ti 3:16-17','1 Jn 5:14','Mt 6:9-13'] },
      { p: '¿Qué nos enseña el prefacio del Padrenuestro?', r: 'El prefacio, «Padre nuestro que estás en los cielos», nos enseña a acercarnos a Dios con toda santa reverencia y confianza, como hijos a un padre capaz y dispuesto a ayudarnos, y que debemos orar con y por los demás.', refs: ['Mt 6:9','Ro 8:15','Lc 11:13','1 Ti 2:1-2'] },
      { p: '¿Qué pedimos en la primera petición?', r: 'En la primera petición, «Santificado sea tu nombre», pedimos que Dios nos capacite a nosotros y a todos para glorificarle en todo aquello por lo cual él se da a conocer, y que disponga todas las cosas para su propia gloria.', refs: ['Sal 67:2-3','Ro 11:36','Ap 4:11'] },
      { p: '¿Qué pedimos en la segunda petición?', r: 'En la segunda petición, «Venga tu reino», pedimos que el reino de Satanás sea destruido, que el reino de la gracia se extienda, que nosotros y otros seamos traídos a él y guardados en él, y que el reino de la gloria sea apresurado.', refs: ['Sal 68:1,18','Ap 12:10-11','2 Ts 3:1','Ro 10:1','Ap 22:20'] },
      { p: '¿Qué pedimos en la tercera petición?', r: 'En la tercera petición, «Hágase tu voluntad, como en el cielo, así también en la tierra», pedimos que Dios, por su gracia, nos haga capaces y dispuestos a conocer, obedecer y someternos a su voluntad en todo, como lo hacen los ángeles en el cielo.', refs: ['Sal 103:20-21','Mt 26:39','Hch 21:14'] },
      { p: '¿Qué pedimos en la cuarta petición?', r: 'En la cuarta petición, «El pan nuestro de cada día, dánoslo hoy», pedimos que, de la libre dádiva de Dios, recibamos una porción suficiente de las cosas buenas de esta vida, y gocemos de su bendición con ellas.', refs: ['Pr 30:8-9','Mt 6:31-33','1 Ti 4:4-5'] },
      { p: '¿Qué pedimos en la quinta petición?', r: 'En la quinta petición, «Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores», pedimos que Dios, por causa de Cristo, nos perdone gratuitamente todos nuestros pecados; lo cual nos anima a pedir con más confianza porque, por su gracia, podemos de corazón perdonar a otros.', refs: ['Sal 51:1-2','Dn 9:17-19','Mt 6:14-15','Mt 18:35'] },
      { p: '¿Qué pedimos en la sexta petición?', r: 'En la sexta petición, «No nos metas en tentación, mas líbranos del mal», pedimos que Dios nos guarde de ser tentados a pecar, o nos sostenga y libre cuando somos tentados.', refs: ['Mt 26:41','2 Co 12:7-8','1 Co 10:13'] },
      { p: '¿Qué nos enseña la conclusión del Padrenuestro?', r: 'La conclusión, «Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén», nos enseña a tomar de solo Dios el aliento para orar, y a alabarle atribuyéndole el reino, el poder y la gloria; y en testimonio de nuestro deseo y seguridad de ser oídos, decimos: Amén.', refs: ['Dn 9:18-19','1 Cr 29:11-13','1 Co 14:16','Ap 22:20'] }
    ]
  }

};
